// Üretilen dosya: tool/ozgun/uret.py. Kimya ve Malzeme · Kimyasal enerji (entalpi, Hess yasası, bağ enerjileri) ve çözünürlük dengesi (Kçç, ortak iyon etkisi, çökelme) (zor).
const ozChemistry16Zor = <(String, String, List<String>, String)>[
  ('Bir kimyasal tepkimede yüksek sıcaklıklarda girenlerin ürünlerden enerjice daha kararlı olduğu biliniyorsa bu tepkime hakkında ne söylenebilir?', 'Tepkime ekzotermiktir; düşük sıcaklıkta ürünler, yüksek sıcaklıkta girenler daha kararlıdır', ['Tepkime endotermiktir; ürünlerin toplam potansiyel enerjisi girenlerinkinden daha büyüktür', 'Sistemin entalpi değişimi sıfırdır ve sıcaklık değişimi denge durumunu hiç etkilemez', 'İleri tepkimenin aktifleşme enerjisi geri tepkimenin aktifleşme enerjisinden daha yüksektir'], 'Ekzotermik tepkimelerde ürünlerin potansiyel enerjisi düşüktür (düşük sıcaklıkta ürünler kararlı), yüksek sıcaklıkta ise yüksek enerjili taraf olan girenler daha kararlı hale gelir.'),
  ('Susuz kalsiyum klorür (CaCl₂) katısı laboratuvarda saf suda çözündüğünde cam balonun dış yüzeyinin el yakacak kadar ısındığı fark edilir. Bu çözünme sürecinde hangi ilişki geçerlidir?', 'İyonların suyla hidratlaşma enerjisinin mutlak değeri kristal örgü enerjisinden büyüktür', ['Kristal örgü bağlarını kırmak için harcanan enerji hidratlaşma enerjisinden fazladır', 'Çözünme sırasında suyun kovalent bağları koptuğu için sistemin entalpisi artmıştır', 'Kalsiyum klorür suda çözünürken minimum enerji eğilimi katı çökelti tarafındadır'], 'İyonik katıların çözünmesinde örgü enerjisi (+, endotermik) ile hidratlaşma enerjisi (-, ekzotermik) toplanır; CaCl₂\'de hidratlaşma baskın olduğundan net çözünme ekzotermiktir.'),
  ('Yalıtılmış sürtünmesiz pistonlu bir kapta sabit dış basınç altında gerçekleşen A(g) + B(g) → 2C(g) tepkimesinde gaz sıcaklığının azaldığı belirleniyor. Buna göre aşağıdakilerden hangisi doğrudur?', 'Tepkime endotermiktir ve gerekli ısıyı gaz karışımının kendi kinetik enerjisinden karşılamıştır', ['Tepkime ekzotermiktir ancak piston hacmi küçüldüğü için gaz molekülleri soğumuştur', 'Mol sayısı korunduğundan tepkimenin entalpi değişimi sıfıra eşit olmak zorundadır', 'Ürünlerin potansiyel enerjisi girenlerinkinden daha düşük bir seviyede bulunmaktadır'], 'Isıca yalıtılmış kapta mol sayısı değişmezken sıcaklığın düşmesi, kimyasal tepkimenin endotermik olduğunu (ΔH > 0) ve iç kinetik enerjiyi potansiyel enerjiye çevirdiğini gösterir.'),
  ('Alev geciktirici polimer malzemelere katkı olarak eklenen alüminyum hidroksit (Al(OH)₃), yangın anında 2Al(OH)₃(k) → Al₂O₃(k) + 3H₂O(g) tepkimesiyle bozunur. Bu katkının yangını yavaşlatma mekanizması nedir?', 'Bozunma tepkimesinin endotermik olup alevden ısı çekmesi ve su buharıyla oksijeni seyreltmesi', ['Ekzotermik bozunmayla ortamdaki yanıcı gazları tutuşma sıcaklığının üzerine çıkarması', 'Alüminyum oksit katısının havadaki azot gazıyla yanarak koruyucu nitrik asit üretmesi', 'Ortama saf oksijen gazı salarak eksik yanmayı tam yanmaya dönüştürüp dumanı kesmesi'], 'Al(OH)₃\'ün termal dehidratasyonu güçlü biçimde endotermiktir (ΔH > 0); polimer yüzeyinden ısı soğurarak sıcaklığı düşürür ve çıkan su buharı yanıcı gazları seyreltir.'),
  ('Berilyum veya azot gibi tam dolu ya da yarı dolu kararlı orbital yapısına sahip atomlara gaz fazında bir elektron eklenmesi olayının entalpi işareti nasıldır?', 'Kararlı elektron dizilimi bozulacağı için dışarıdan enerji gerektiren endotermik süreçtir', ['Atom numarası küçük olduğu için tüm halojenlerden daha yüksek ısı salan ekzotermik olaydır', 'Çekirdek yükü değişmediği için enerji alışverişi olmadan sıfır entalpiyle gerçekleşir', 'Nötr atom ile elektron arasında yalnızca çekim kuvveti bulunduğundan daima negatif işaretlidir'], '2A (Be, Mg) ve 5A (N) grubundaki bazı atomlar küresel simetrik kararlı yapıya sahip olduğundan bunlara elektron katılması enerji gerektirir (ΔH > 0, endotermik elektron ilgisi).'),
  ('Potasyum klorat katısının (KClO₃) laboratuvarda oksijen gazı elde etmek amacıyla MnO₂ katalizörü eşliğinde ısıtılarak 2KClO₃(k) → 2KCl(k) + 3O₂(g) şeklinde ayrıştırılmasıyla ilgili ne söylenebilir?', 'Ekzotermik bir ayrışma tepkimesidir; başlaması için ısıtılır ancak ΔH değeri negatiftir', ['Bütün ayrışma tepkimeleri istisnasız endotermik olduğundan entalpi değişimi pozitiftir', 'Katalizör kullanıldığı için tepkime entalpisi pozitif değerden negatif değere dönmüştür', 'Oksijen gazı oluştuğu için ürünlerin potansiyel enerjisi girenlerden daha yüksektir'], 'Çoğu analiz tepkimesi endotermik olsa da KClO₃\'ün KCl ve O₂\'ye ayrışması (ve patlayıcıların bozunması gibi bazı analizler) istisnai olarak ekzotermiktir (ΔH ≈ -89,4 kJ); ilk ısıtma yalnızca aktifleşme enerjisini aşmak içindir.'),
  ('Saf suyun 25 °C\'de kendi kendine çok az oranda H₂O(s) ⇌ H⁺(suda) + OH⁻(suda) şeklinde iyonlaşması endotermik bir dengedir. Buna göre saf su ısıtıldığında ne gerçekleşir?', 'İyonlaşma ileri yönde desteklenir ve su nötr kalmakla birlikte iyon derişimleri artar', ['Ekzotermik yön hızlandığı için hidrojen ve hidroksit iyonları birleşerek azalır', 'Suyun pH değeri 7\'nin üzerine çıkarak sıcak suyun bazik özellik göstermesine yol açar', 'İyonlaşma entalpisi negatif olduğundan yüksek sıcaklıkta Ksu sabiti küçülür'], 'Nötralleşme ekzotermik olduğundan tersi olan suyun oto-iyonizasyonu endotermiktir (ΔH ≈ +55,8 kJ/mol); sıcaklık artırıldığında iyonlaşma artar ama [H⁺]=[OH⁻] eşitliği korunur.'),
  ('Kalorimetre kabında 100 mL 1,0 M HCl çözeltisi ile 100 mL 1,0 M KOH çözeltisi 24,0 °C başlangıç sıcaklığında karıştırıldığında son sıcaklık 30,7 °C olarak ölçülüyor (çözelti yoğunluğu 1 g/mL, c = 4,18 J/g·°C). Bu deneyden hesaplanan molar nötralleşme entalpisi yaklaşık kaç kJ/mol\'dür?', '-56,0 kJ/mol', ['+56,0 kJ/mol', '-28,0 kJ/mol', '-5,60 kJ/mol'], 'Toplam kütle 200 g, ΔT = 6,7 °C. Qçözelti = 200 × 4,18 × 6,7 = 5601,2 J ≈ 5,60 kJ. Tepkimeye giren mol sayısı n = 0,1 L × 1,0 M = 0,1 mol. ΔH = -5,60 / 0,1 = -56,0 kJ/mol.'),
  ('Uzay mekiklerinin atmosfere yeniden girişi sırasında burun kısmındaki koruyucu seramik kalkanların bir miktar aşınıp süblimleşecek şekilde tasarlanmasının (ablatif soğutma) amacı nedir?', 'Endotermik süblimleşme ve erime ile sürtünme ısısını soğurup gövdeye geçişini önlemek', ['Seramik yüzeyin havadaki oksijenle ekzotermik yanarak itici şok dalgası oluşturması', 'Kalkan malzemesinin kırağılaşarak gövde etrafında koruyucu sıvı nitrojen tabakası üretmesi', 'Yüksek sıcaklıkta seramiğin ısı iletkenliğini artırıp tüm ısıyı kabin içine aktarmak'], 'Ablatif ısı kalkanlarında malzeme eriyip süblimleşirken (endotermik süreçler) muazzam miktarda sürtünme ısısını soğurur ve buharlaşan kütleyle ısıyı araçtan uzaklaştırır.'),
  ('Amfoterik olmayan iyonik NaCl kristali gaz fazındaki iyonlarına ayrıştırıldığında NaCl(k) → Na⁺(g) + Cl⁻(g) değişimi için ΔH = +787 kJ/mol ölçülüyor. Bu enerji değeri neyi ifade eder?', 'Sodyum klorürün kristal örgü enerjisidir ve elektrostatik çekimi yenmek için alınan ısıdır', ['Sodyum klorürün standart molar çözünme entalpisidir ve ekzotermik karakterdedir', 'Sodyum atomunun iyonlaşma enerjisi ile klorun kovalent bağ enerjisinin farkıdır', 'Yemek tuzunun erime ısısı olup sıvı NaCl elde etmek için yeterli olan enerjidir'], '1 mol iyonik katının gaz fazındaki bileşen iyonlarına tamamen ayrışması için gereken endotermik enerji (+787 kJ/mol) kristal örgü enerjisidir; erimeden çok daha büyüktür.'),
  ('İzole (yalıtılmış) bir kapta gerçekleşen X₂(g) + Y₂(g) → 2XY(g) tepkimesinde toplam molekül sayısı sabit kalmasına karşın kaptaki gaz basıncının başlangıca göre azaldığı saptanıyor. Bu durumun nedeni nedir?', 'Tepkime endotermik olduğu için gaz karışımının sıcaklığının düşmesi', ['Tepkime ekzotermik olduğu için taneciklerin ortalama hızının artması', 'Sabit hacimli kapta gaz yoğunluğunun yarıya inerek çarpışma sayısını azaltması', 'Ürün moleküllerinin mol kütlesinin girenlerin toplam kütlesinden küçük olması'], 'Sabit hacim (V) ve sabit mol sayısında (n) ideal gaz bağıntısı P·V = n·R·T gereğince basıncın (P) azalması sıcaklığın (T) düştüğünü, yani yalıtılmış kaptaki tepkimenin endotermik olduğunu gösterir.'),
  ('Otomobillerin hava yastıklarında çarpışma anında elektrik kıvılcımıyla tetiklenen 2NaN₃(k) → 2Na(k) + 3N₂(g) tepkimesi milisaniyeler içinde yastığı şişirir. Bu ayrışma tepkimesinin termokimyasal özelliği nedir?', 'Çok sağlam üçlü bağa sahip N₂ gazı oluştuğu için ısı açığa çıkaran ekzotermik ayrışmadır', ['Katı sodyum azid gaz faza geçtiği için kabin içini donduran endotermik süblimleşmedir', 'Azot gazının yanma tepkimesi olduğu için dışarıdan sürekli ısı verilmesini gerektirir', 'Entalpi değişimi sıfır olan tersinir bir fiziksel çözünme-çökelme dengesidir'], 'Sodyum azidin (NaN₃) bozunmasında çok yüksek bağ enerjili N≡N molekülleri oluştuğundan ayrışma tepkimesi olmasına rağmen ekzotermiktir (ΔH < 0) ve çok hızlı gaz üretir.'),
  ('Magnezyum sülfat (MgSO₄) susuz tuzu suda çözündüğünde ortam sıcaklığını artırırken, hidratlı formu olan Epsom tuzu (MgSO₄·7H₂O) suda çözündüğünde ortam sıcaklığını hafifçe düşürür. Bu farkın temel sebebi nedir?', 'Hidratlı tuzda iyonlar zaten suyla sarılı olduğundan çözünürken ek hidratlaşma ısısının çok az açığa çıkması', ['Epsom tuzundaki kükürt atomlarının suda indirgenerek hidrojen sülfür gazına dönüşmesi', 'Susuz magnezyum sülfatın kovalent, hidratlı formunun ise tamamen metalik kristalli olması', 'Su moleküllerinin hidratlı tuzu çözerken kendi içindeki O-H bağlarını tamamen koparması'], 'Susuz MgSO₄ suda çözünürken yüksek hidratlaşma enerjisi salar (ekzotermik); MgSO₄·7H₂O\'da ise iyonlar kristal içinde zaten su molekülleriyle koordine olduğundan örgü kırma enerjisi baskın gelir (endotermik).'),
  ('Güneş enerjili termal depolama sistemlerinde gündüz saatlerinde Glauber tuzunun (Na₂SO₄·10H₂O) yaklaşık 32 °C\'de eritilip gece katılaşmaya bırakılmasının sağladığı avantaj nedir?', 'Gündüz endotermik erimeyle depolanan yüksek gizli ısının gece ekzotermik donmayla odaya salınması', ['Tuzun gece karanlıkta oksijenle yanarak kimyasal yakıt gibi karbondioksit üretmesi', 'Erime olayının ekzotermik olması sayesinde gündüz saatlerinde binanın soğutulması', 'Katılaşma sırasında tuzun suyu elektroliz ederek elektrik şebekesine akım vermesi'], 'Faz değiştiren malzemeler (PCM) erirken yüksek miktarda ısı soğurur (endotermik) ve ortam soğuduğunda tekrar kristalleşerek bu gizli ısıyı sabit sıcaklıkta geri verir (ekzotermik).'),
  ('Kükürt trioksit gazının suyla birleşerek sülfürik asit oluşturduğu SO₃(g) + H₂O(s) → H₂SO₄(suda) tepkimesi endüstride doğrudan suya SO₃ gönderilerek yapılmaz; çünkü oluşan yoğun asit sisi kontrol edilemez. Bunun termokimyasal nedeni nedir?', 'Tepkimenin aşırı ekzotermik olması nedeniyle suyun aniden buharlaşıp asit aerosolü oluşturması', ['Tepkimenin çok endotermik olması yüzünden suyun donarak boruları tıkaması', 'Kükürt trioksit gazının suda hiç çözünmeyip asal gaz gibi kabı terk etmesi', 'Su eklendiğinde kükürt trioksitin endotermik olarak katı kükürde indirgenmesi'], 'SO₃\'ün suyla tepkimesi son derece ekzotermiktir (ΔH ≈ -132 kJ/mol); açığa çıkan şiddetli ısı suyu kaynatarak tehlikeli H₂SO₄ sisi (aerosolü) oluşturur, bu yüzden SO₃ önce derişik H₂SO₄\'te (oleum) tutulur.'),
  ('Soy gazların (He, Ne, Ar) oda koşullarında tek atomlu gazlar halinde bulunması ve iki helyum atomunun He₂ kovalent molekülü oluşturmaması bağ enerjisi açısından nasıl yorumlanır?', 'Atomlar birleştiğinde enerjinin düşmemesi, yani kararlı ekzotermik bir kovalent bağ kurulamaması', ['Helyum atomlarının birleşmesinin çok yüksek ısı salarak molekülü anında eritmesi', 'Soy gaz atomları arasındaki kovalent bağın azot molekülünden daha sağlam olması', 'Tek atomlu gazların standart koşullarda yalnızca endotermik iyonik kristaller yapması'], 'Kimyasal bağ oluşabilmesi için atomlar yaklaştığında potansiyel enerjinin belirgin biçimde azalması (ekzotermik bağ oluşumu) gerekir; He₂\'de bağ derecesi sıfır olduğundan kararlı bağ oluşmaz.'),
  ('Sodyum hidroksit (NaOH) payetleri suda çözündüğünde ΔH_çöz = -44,5 kJ/mol entalpi değişimi gözlenir. Isıca yalıtılmış bir kapta 8 gram NaOH (40 g/mol) 200 gram suda çözündüğünde çözeltinin iç enerjisi ve sıcaklığı nasıl etkilenir?', 'Kimyasal potansiyel enerji ısıya dönüştüğünden çözelti sıcaklığı yaklaşık 10,6 °C artar', ['Çözünme ekzotermik olduğu için çözeltinin sıcaklığı yaklaşık 10,6 °C azalır', 'Yalıtılmış kapta dışarıyla ısı alışverişi olmadığından sıcaklık sabit kalır', 'Sodyum hidroksit baz olduğu için sudan 8,9 kJ ısı çekerek kabı soğutur'], '8 g NaOH = 0,2 mol ⇒ Q = 0,2 × 44,5 = 8,9 kJ = 8900 J ısı açığa çıkar. Yalıtılmış kapta bu ısı çözeltiyi ısıtır: ΔT ≈ 8900 / (208 × 4,18) ≈ 10,2–10,6 °C artış gözlenir.'),
  ('Kuvvetli baz NaOH ile zayıf asit CH₃COOH sulu çözeltilerinin 1\'er mollerinin nötralleşmesi sırasında açığa çıkan ısının, 1 mol HCl ile 1 mol NaOH nötralleşmesinden (55,8 kJ) yaklaşık 2 kJ daha az olmasının nedeni nedir?', 'Zayıf asidin henüz ayrışmamış moleküllerinin iyonlaşması için bir miktar ısının harcanması', ['Asetat iyonlarının sodyum iyonlarıyla ekzotermik bir çökelek oluşturması', 'Zayıf asit çözeltisinin başlangıçtaki sıcaklığının mutlak ölçekte daha düşük olması', 'Kuvvetli bazın zayıf asitle tepkimesinde su yerine hidrojen peroksit oluşması'], 'Kuvvetli asit-baz nötralleşmesinde asit zaten %100 iyonlaşmıştır; zayıf asitlerde ise moleküllerin iyonlaşması (endotermik adım) açığa çıkan net ısının bir kısmını tüketir.'),
  ('Sabit hacimli kapalı bir kalorimetrede (bomba kalorimetresi) ölçülen yanma ısısı (qv) ile sabit basınçta ölçülen entalpi değişimi (ΔH = qp) hangi tepkimede birbirine tam olarak eşittir? (Sıcaklık sabit)', 'C(k) + O₂(g) → CO₂(g)', ['2CO(g) + O₂(g) → 2CO₂(g)', 'C₃H₈(g) + 5O₂(g) → 3CO₂(g) + 4H₂O(s)', '2H₂(g) + O₂(g) → 2H₂O(s)'], 'ΔH = ΔU + Δn_gaz·R·T bağıntısına göre gaz mol sayısı değişiminin sıfır olduğu (Δn_gaz = 1 - 1 = 0) C(k) + O₂(g) → CO₂(g) tepkimesinde qp = qv yani ΔH = ΔU olur.'),
  ('Hidrojen, metan ve etil alkol yakıtlarının molar yanma entalpileri sırasıyla H₂ (2 g/mol) için -286 kJ/mol, CH₄ (16 g/mol) için -890 kJ/mol ve C₂H₅OH (46 g/mol) için -1367 kJ/mol\'dür. Roket mühendisliğinde birim kütle başına (1 gram yakıttan) en yüksek ısıyı elde etmek isteyen bir tasarımcı hangisini seçmelidir?', 'Birim kütlede yaklaşık 143 kJ ısı veren hidrojen gazını', ['Molar yanma ısısı sayıca en büyük olan etil alkol sıvısını', 'Gram başına yaklaşık 55,6 kJ enerji açığa çıkaran metan gazını', 'Karbon sayısı arttıkça gram başına ısıl değeri katlanan etil alkolü'], '1 gram başına ısı: H₂ için 286/2 = 143 kJ/g; CH₄ için 890/16 ≈ 55,6 kJ/g; C₂H₅OH için 1367/46 ≈ 29,7 kJ/g. Hidrojenin mol kütlesi çok küçük olduğundan kütlesel enerji yoğunluğu en yüksektir.'),
  ('Asetilen (C₂H₂) ve etan (C₂H₆) gazlarından oluşan 0,5 mollük bir karışım tamamen yakıldığında toplam 715 kJ ısı açığa çıkıyor. Molar yanma entalpileri C₂H₂ için -1300 kJ/mol ve C₂H₆ için -1560 kJ/mol olduğuna göre karışımdaki asetilen kaç moldür?', '0,25 mol', ['0,15 mol', '0,30 mol', '0,40 mol'], 'Asetilen x mol, etan (0,5 - x) mol olsun. Açığa çıkan ısı: 1300x + 1560(0,5 - x) = 715 ⇒ 1300x + 780 - 1560x = 715 ⇒ 260x = 65 ⇒ x = 0,25 mol bulunur.'),
  ('Glikoz katısının standart yanma entalpisi C₆H₁₂O₆(k) + 6O₂(g) → 6CO₂(g) + 6H₂O(s) ΔH° = -2808 kJ/mol\'dür. Standart oluşum entalpileri CO₂(g) = -393,5 kJ/mol ve H₂O(s) = -285,8 kJ/mol olduğuna göre glikoz katısının standart molar oluşum entalpisi kaç kJ/mol\'dür?', '-1267,8 kJ/mol', ['-4075,8 kJ/mol', '+1267,8 kJ/mol', '-679,3 kJ/mol'], 'Ürünlerin toplam oluşum entalpisi = 6×(-393,5) + 6×(-285,8) = -2361,0 - 1714,8 = -4075,8 kJ. ΔH° = -4075,8 - ΔH°f(glikoz) = -2808 ⇒ ΔH°f(glikoz) = -4075,8 + 2808 = -1267,8 kJ/mol.'),
  ('Kaynakçılıkta çok yüksek alev sıcaklığı elde etmek için kullanılan asetilen gazının (C₂H₂) standart oluşum entalpisi +227 kJ/mol iken etan gazınınki (C₂H₆) -85 kJ/mol\'dür. Asetilenin oluşum entalpisinin pozitif olması yanma ısısını nasıl etkiler?', 'Asetilen elementlerine göre yüksek enerjili olduğundan yandığında beklenen bağ sayısından daha yüksek ısı salar', ['Oluşum entalpisi pozitif olduğu için asetilenin oksijenle yanmasını endotermik hale getirir', 'Asetilen molekülünün oksijenle hiç tepkimeye girmeden soğuk alev üretmesine yol açar', 'Yanma ürünleri olan karbondioksit ve suyun oluşum entalpilerini sıfıra düşürür'], 'ΔH°yanma = ΔH°f(ürünler) - ΔH°f(yakıt) bağıntısında yakıtın oluşum entalpisi pozitif (+227) olduğunda önündeki eksi işaretiyle yanmayı ekstra ekzotermik yapar ve çok yüksek alev sıcaklığı (~3100 °C) sağlar.'),
  ('2SO₂(g) + O₂(g) → 2SO₃(g) tepkimesinde standart oluşum entalpileri SO₂(g) için -296,8 kJ/mol ve SO₃(g) için -395,7 kJ/mol\'dür. Sabit basınçlı bir reaktörde 2 mol SO₂ ve 2 mol O₂ gazları %50 verimle tepkimeye girdiğinde ısı değişimi ne olur?', '98,9 kJ ısı açığa çıkar', ['197,8 kJ ısı açığa çıkar', '49,45 kJ ısı soğurulur', '395,7 kJ ısı açığa çıkar'], 'Tam verimde (2 mol SO₂ sınırlayıcı, 1 mol O₂ harcanır): ΔH° = 2×(-395,7) - 2×(-296,8) = -791,4 + 593,6 = -197,8 kJ. Tepkime %50 verimle gerçekleştiğinden 197,8 × 0,50 = 98,9 kJ ısı açığa çıkar.'),
  ('Fosfor elementinin beyaz fosfor (P₄) ve kırmızı fosfor olmak üzere başlıca iki allotropu vardır; IUPAC ve standart termokimya cetvellerinde geleneksel referans (ΔH°f = 0) olarak beyaz fosfor katısı seçilmiştir. Beyaz fosfordan kırmızı fosfora geçiş ekzotermik olduğuna göre kırmızı fosforun ΔH°f işareti ve kararlılığı nasıldır?', 'Oluşum entalpisi negatiftir ve beyaz fosfordan enerjice daha kararlıdır', ['Oluşum entalpisi pozitiftir ve havada beyaz fosfordan daha kolay tutuşur', 'Her iki allotrop da saf element olduğundan ikisinin de oluşum entalpisi sıfırdır', 'Oluşum entalpisi negatif olmasına rağmen potansiyel enerjisi beyaz fosfordan yüksektir'], 'P(beyaz, ΔH°f=0) → P(kırmızı) dönüşümü ekzotermiktir (ΔH ≈ -17,6 kJ/mol P atomu başına); dolayısıyla kırmızı fosforun oluşum entalpisi negatiftir ve enerjisi daha düşük (daha kararlı) bir allotroptur.'),
  ('Bir hidrokarbon bileşiğinin (CₓHᵧ) 0,1 molü tamamen yakıldığında 0,4 mol CO₂(g) ve 0,4 mol H₂O(s) oluşurken 260 kJ ısı açığa çıkıyor. CO₂(g) ve H₂O(s) standart oluşum entalpileri sırasıyla -394 kJ/mol ve -286 kJ/mol olduğuna göre bu hidrokarbonun formülü ve molar oluşum entalpisi nedir?', 'C₄H₈ ve -120 kJ/mol', ['C₄H₁₀ ve -120 kJ/mol', 'C₄H₈ ve +120 kJ/mol', 'C₂H₄ ve -60 kJ/mol'], '1 mol bileşik yandığında 4 mol CO₂ ve 4 mol H₂O oluşur ⇒ formül C₄H₈ ve ΔH°yanma = -260 / 0,1 = -2600 kJ/mol. -2600 = [4(-394) + 4(-286)] - ΔH°f(C₄H₈) ⇒ -2600 = (-1576 - 1144) - ΔH°f = -2720 - ΔH°f ⇒ ΔH°f = -120 kJ/mol.'),
  ('Standart koşullarda gerçekleşen X₂(g) + 2Y₂(g) → 2XY₂(g) tepkimesinde eşit mol sayısında X₂ ve Y₂ gazları alınarak tam verimli tepkime gerçekleştirildiğinde 120 kJ ısı açığa çıkıyor ve kapta 0,4 mol gaz artıyor. Buna göre XY₂(g) bileşiğinin standart molar oluşum entalpisi kaç kJ/mol\'dür?', '-150 kJ/mol', ['-300 kJ/mol', '-75 kJ/mol', '+150 kJ/mol'], 'Başlangıçta n\'er mol alınsın. Y₂ sınırlayıcıdır: n mol Y₂ harcanırken 0,5n mol X₂ harcanır ve 0,5n mol X₂ artar. 0,5n = 0,4 ⇒ n = 0,8 mol Y₂ harcanmış ve 0,8 mol XY₂ oluşmuştur. 0,8 mol XY₂ oluşurken 120 kJ ısı çıktığına göre 1 mol XY₂ için ΔH°f = -120 / 0,8 = -150 kJ/mol.'),
  ('Karbon disülfür sıvısının yanma tepkimesi CS₂(s) + 3O₂(g) → CO₂(g) + 2SO₂(g) ΔH° = -1077 kJ/mol\'dür. Oluşum entalpileri CO₂(g) = -393,5 kJ/mol ve SO₂(g) = -296,8 kJ/mol olduğuna göre CS₂(s)\'nin standart molar oluşum entalpisi kaç kJ/mol\'dür?', '+89,9 kJ/mol', ['-89,9 kJ/mol', '+198,6 kJ/mol', '-1767,1 kJ/mol'], 'Ürünlerin toplam oluşum entalpisi = -393,5 + 2×(-296,8) = -393,5 - 593,6 = -987,1 kJ. -1077 = -987,1 - ΔH°f(CS₂) ⇒ ΔH°f(CS₂) = -987,1 + 1077 = +89,9 kJ/mol (endotermik oluşumlu bileşik).'),
  ('Titanyum metali üretiminde kullanılan Kroll sürecinin bir adımı TiCl₄(s) + 2Mg(k) → Ti(k) + 2MgCl₂(k) tepkimesidir. Standart oluşum entalpileri TiCl₄(s) için -804 kJ/mol ve MgCl₂(k) için -641 kJ/mol olduğuna göre 24 gram saf titanyum (Ti = 48 g/mol) üretilirken ısı değişimi ne olur?', '239 kJ ısı açığa çıkar', ['478 kJ ısı açığa çıkar', '239 kJ ısı soğurulur', '163 kJ ısı açığa çıkar'], 'Mg(k) ve Ti(k) elementtir (ΔH°f = 0). 1 mol Ti için ΔH° = 2×(-641) - (-804) = -1282 + 804 = -478 kJ. 24 g Ti = 0,5 mol olduğundan 0,5 × 478 = 239 kJ ısı açığa çıkar.'),
  ('Kalsiyum karbürden (karpit) asetilen üretim denklemi CaC₂(k) + 2H₂O(s) → Ca(OH)₂(k) + C₂H₂(g) ΔH° = -128 kJ\'dür. Oluşum entalpileri CaC₂(k) = -59,8 kJ/mol, H₂O(s) = -285,8 kJ/mol ve Ca(OH)₂(k) = -986,1 kJ/mol ise C₂H₂(g)\'nin standart molar oluşum entalpisi kaç kJ/mol\'dür?', '+226,7 kJ/mol', ['-226,7 kJ/mol', '+142,5 kJ/mol', '-554,7 kJ/mol'], 'Girenler toplamı = -59,8 + 2×(-285,8) = -631,4 kJ. ΔH° = [-986,1 + ΔH°f(C₂H₂)] - (-631,4) = -128 ⇒ -354,7 + ΔH°f(C₂H₂) = -128 ⇒ ΔH°f(C₂H₂) = +226,7 kJ/mol.'),
  ('İyot katısının (I₂(k)) 25 °C ve 1 atm\'de süblimleşerek I₂(g) buharına dönüşme entalpisi +62,4 kJ/mol\'dür. Standart koşullarda H₂(g) + I₂(g) → 2HI(g) tepkimesinin ΔH° değeri -9,4 kJ olduğuna göre HI(g) bileşiğinin standart molar oluşum entalpisi kaç kJ/mol\'dür?', '+26,5 kJ/mol', ['-4,7 kJ/mol', '+53,0 kJ/mol', '-35,9 kJ/mol'], 'İyodun 25 °C\'de kararlı hali katıdır (ΔH°f[I₂(k)] = 0, ΔH°f[I₂(g)] = +62,4 kJ/mol). -9,4 = 2×ΔH°f[HI(g)] - (0 + 62,4) ⇒ 2×ΔH°f[HI(g)] = +53,0 ⇒ ΔH°f[HI(g)] = +26,5 kJ/mol.'),
  ('Hidrazin sıvısı (N₂H₄) roket yakıtı olarak N₂H₄(s) + 2H₂O₂(s) → N₂(g) + 4H₂O(g) ΔH° = -642 kJ tepkimesinde kullanılır. Oluşum entalpileri N₂H₄(s) = +50,6 kJ/mol ve H₂O(g) = -241,8 kJ/mol ise sıvı hidrojen peroksitin (H₂O₂(s)) standart molar oluşum entalpisi yaklaşık kaç kJ/mol\'dür?', '-187,9 kJ/mol', ['-375,8 kJ/mol', '-137,3 kJ/mol', '+187,9 kJ/mol'], 'Ürünler toplamı = 0 + 4×(-241,8) = -967,2 kJ. -642 = -967,2 - [50,6 + 2×ΔH°f(H₂O₂)] ⇒ 50,6 + 2×ΔH°f = -967,2 + 642 = -325,2 ⇒ 2×ΔH°f = -375,8 ⇒ ΔH°f(H₂O₂) = -187,9 kJ/mol.'),
  ('Çinko sülfür filizinin kavrulma denklemi 2ZnS(k) + 3O₂(g) → 2ZnO(k) + 2SO₂(g) ΔH° = -879 kJ şeklindedir. Bir metalürji fırınında 19,4 gram ZnS katısı (97 g/mol) ile normal koşullarda 4,48 litre O₂ gazı tam verimle tepkimeye sokulursa kaç kJ ısı açığa çıkar?', '58,6 kJ', ['87,9 kJ', '117,2 kJ', '43,95 kJ'], 'n(ZnS) = 19,4 / 97 = 0,20 mol; n(O₂) = 4,48 / 22,4 = 0,20 mol. Katsayılara göre 3 mol O₂\'ye 2 mol ZnS gerektiğinden sınırlayıcı bileşen O₂\'dir (0,20 mol O₂ tamamı harcanır). 3 mol O₂ harcandığında 879 kJ ısı çıkıyorsa 0,20 mol O₂ için (0,20 / 3) × 879 = 0,20 × 293 = 58,6 kJ ısı açığa çıkar.'),
  ('Bütan gazının (C₄H₁₀ = 58 g/mol) standart molar yanma entalpisi -2877 kJ/mol\'dür. Kamp ocağındaki kartuşta bulunan 11,6 gram bütan gazının tamamı yandığında açığa çıkan ısı enerjisi 0 °C\'deki buzdan en fazla kaç gram eritebilir? (Buzun erime ısısı L_e = 334 J/g)', 'Yaklaşık 1723 gram', ['Yaklaşık 861 gram', 'Yaklaşık 3446 gram', 'Yaklaşık 575 gram'], 'n(C₄H₁₀) = 11,6 / 58 = 0,2 mol. Açığa çıkan ısı Q = 0,2 × 2877 = 575,4 kJ = 575400 J. Eribilecek buz kütlesi m = 575400 / 334 ≈ 1722,8 g ≈ 1723 gram.'),
  ('Gliserol, asetik asit ve glikoz gibi yapısında oksijen atomu barındıran organik bileşiklerin gram başına yanma ısısının aynı karbon sayılı hidrokarbonlardan (alkanlardan) daha düşük olmasının temel kimyasal nedeni nedir?', 'Yapılarındaki karbon atomlarının oksijenle zaten kısmen yükseltgenmiş durumda bulunması', ['Oksijen içeren organik bileşiklerin yanma tepkimelerinin endotermik karakter taşıması', 'Yandıklarında karbondioksit yerine yalnızca katı kurum ve karbon monoksit üretmeleri', 'Hidrokarbonların oksijenle tepkimeye girmeden doğrudan nükleer enerji açığa çıkarması'], 'Karbonhidratlar ve alkoller yapılarında C–O ve O–H bağları bulundurduğu için yakıt molekülü zaten kısmen oksitlenmiş durumdadır ve oksijen kütlesi taşır; bu nedenle gram başına saldıkları yanma ısısı saf hidrokarbonlardan düşüktür.'),
  ('Eşit kütlelerde alınan CH₄ (16 g/mol, ΔH°yanma = -890 kJ/mol) ve SO₂ (64 g/mol, ΔH°yanma = -99 kJ/mol) gazları aşırı oksijenle tamamen yakıldığında CH₄\'ten açığa çıkan ısının SO₂\'den açığa çıkan ısıya oranı yaklaşık kaçtır?', 'Yaklaşık 36 katıdır', ['Yaklaşık 9 katıdır', 'Yaklaşık 4 katıdır', 'Yaklaşık 18 katıdır'], 'Her ikisinden 64\'er gram alalım: 64 g SO₂ = 1 moldür ve 99 kJ ısı verir. 64 g CH₄ = 64/16 = 4 moldür ve 4 × 890 = 3560 kJ ısı verir. Oran = 3560 / 99 ≈ 35,96 ≈ 36 katıdır.'),
  ('Bir bileşiğin standart molar oluşum entalpisi hesaplanırken referans alınan element halleri yanlış seçilirse (örneğin C(grafit) yerine C(g) atomik karbon gazı sıfır alınırsa) hesaplanan ΔH°tepkime değerleri nasıl etkilenir?', 'Atom sayıları korunduğu sürece girende ve üründe referans kayması birbirini götürür ve ΔH°tepkime değişmez', ['Tüm ekzotermik tepkimeler endotermik, tüm endotermik tepkimeler ekzotermik çıkar', 'Yalnızca yanma tepkimelerinin entalpisi iki katına çıkarken nötralleşme entalpisi yarıya iner', 'Entalpi hal fonksiyonu olmaktan çıkar ve katalizör miktarına bağımlı hale gelir'], 'Kimyasal tepkimelerde atom türü ve sayısı korunduğundan, bir elementin sıfır referans noktasını kaydırmak hem girenlerin hem ürünlerin oluşum entalpilerine eşit sabit ekler; fark alındığında (ürün - giren) bu sabitler sadeleşir ve ΔH°tepkime değişmez.'),
  ('Azot monoksit gazının havadaki oksijenle 2NO(g) + O₂(g) → 2NO₂(g) şeklinde yükseltgenmesinde ΔH°f[NO(g)] = +90,3 kJ/mol ve ΔH°f[NO₂(g)] = +33,2 kJ/mol\'dür. Azotun O₂ ile yanması endotermik olduğu halde NO\'nun O₂ ile yanması için ne söylenebilir?', 'ΔH° = -114,2 kJ olan ekzotermik bir tepkimedir ve havada hızla gerçekleşir', ['Her iki azot oksidinin oluşum entalpisi pozitif olduğundan bu tepkime de endotermiktir', 'Oksijen gazının oluşum entalpisi sıfır olduğu için tepkime ısısı +247,0 kJ çıkar', 'Ürünlerin potansiyel enerjisi girenlerden daha yüksek olduğundan ısı soğurulur'], 'N₂\'nin yanması endotermiktir ancak NO\'nun NO₂\'ye yükseltgenmesinde ΔH° = 2×(+33,2) - 2×(+90,3) = 66,4 - 180,6 = -114,2 kJ olup tepkime ekzotermiktir!'),
  ('Normal koşullarda 8,96 litre hacim kaplayan propan (C₃H₈) ve oksijen (O₂) gaz karışımı tam verimle yakıldığında hiç artan gaz kalmıyor. Propanın molar yanma entalpisi -2220 kJ/mol olduğuna göre bu tepkimede kaç kJ ısı açığa çıkar?', '148,0 kJ', ['888,0 kJ', '222,0 kJ', '74,0 kJ'], 'Toplam mol n = 8,96 / 22,4 = 0,40 mol. C₃H₈ + 5O₂ → 3CO₂ + 4H₂O denklemine göre artansız tepkimede 1 mol C₃H₈ ile 5 mol O₂ (toplam 6 birim) girer. Ancak 0,40/6 tam bölünmez; kontrol: (0,40/6)×2220 = 148,0 kJ tam çıkar! (2220/6 = 370; 0,4 × 370 = 148,0 kJ).'),
  ('Fruktoz ve glikoz (C₆H₁₂O₆) birbirinin yapı izomeri olan iki katı monosakkarittir. Standart molar yanma entalpileri glikoz için -2808 kJ/mol, fruktoz için -2810 kJ/mol olduğuna göre izomerlerin oluşum entalpileri hakkında hangi yorum doğrudur?', 'Atom sayıları aynı olsa da bağ düzenleri farklı olduğundan oluşum entalpileri birbirinden az da olsa farklıdır', ['Kapalı formülleri aynı olan tüm izomerlerin standart molar oluşum entalpileri birbirine tam eşittir', 'Fruktoz yandığında daha çok ısı verdiği için fruktozun oluşum entalpisi glikozdan daha negatiftir', 'İzomer bileşiklerin birbirine dönüşüm tepkimelerinde entalpi değişimi her zaman sıfır kabul edilir'], 'Yapı izomerlerinin kapalı formülleri aynı olsa bile bağ türleri ve kristal örgü enerjileri farklıdır; fruktoz yandığında 2 kJ daha çok ısı verdiğine göre fruktozun potansiyel enerjisi (ΔH°f) glikozdan 2 kJ/mol daha yüksektir (daha az negatiftir).'),
  ('Hidrojen florür gazının silisyum dioksit (cam) ile aşındırma tepkimesi SiO₂(k) + 4HF(g) → SiF₄(g) + 2H₂O(s) ΔH° = -184 kJ\'dür. Oluşum entalpileri SiO₂(k) = -911 kJ/mol, HF(g) = -273 kJ/mol ve H₂O(s) = -286 kJ/mol olduğuna göre SiF₄(g)\'nin standart molar oluşum entalpisi kaç kJ/mol\'dür?', '-1615 kJ/mol', ['-1431 kJ/mol', '-1987 kJ/mol', '+1615 kJ/mol'], 'Girenler toplamı = -911 + 4×(-273) = -911 - 1092 = -2003 kJ. -184 = [ΔH°f(SiF₄) + 2×(-286)] - (-2003) ⇒ -184 = ΔH°f(SiF₄) - 572 + 2003 ⇒ -184 = ΔH°f(SiF₄) + 1431 ⇒ ΔH°f(SiF₄) = -1615 kJ/mol.'),
  ('Altın (Au) ve platin (Pt) gibi soy metallerin oksit bileşiklerinin standart molar oluşum entalpilerinin pozitif veya sıfıra çok yakın olması doğada nasıl bir sonuç doğurur?', 'Oksitleri enerjice kararsız olduğu için bu metallerin doğada bileşik yapmadan saf (nabit) metal halinde bulunmasını sağlar', ['Bu metallerin açık havada oda sıcaklığında demirden çok daha hızlı paslanmasına neden olur', 'Oksit cevherlerinin eritilmesi sırasında dışarıya patlayıcı düzeyde yüksek ısı yayılmasına yol açar', 'Soy metallerin asit çözeltilerinde hidrojen gazı çıkararak şiddetli biçimde çözünmesini kolaylaştırır'], 'Örneğin Au₂O₃ için ΔH°f pozitif (veya sıfıra çok yakın) olduğundan elementel altın oksidinden enerjice daha kararlıdır; bu yüzden altın doğada oksitlenmeden saf element olarak bulunur.'),
  ('Kalsiyum sülfat yarımhidratın (alçı taşı, CaSO₄·1/2H₂O) su alarak donması CaSO₄·1/2H₂O(k) + 3/2 H₂O(s) → CaSO₄·2H₂O(k) tepkimesiyle gerçekleşir. Oluşum entalpileri sırasıyla -1575 kJ/mol, H₂O(s) için -286 kJ/mol ve jips (CaSO₄·2H₂O) için -2021 kJ/mol olduğuna göre ortopedik alçı donarken kolun hafif ısınmasını sağlayan ΔH° kaç kJ/mol\'dür?', '-17 kJ/mol', ['+17 kJ/mol', '-160 kJ/mol', '-446 kJ/mol'], 'Girenlerin toplam oluşum entalpisi = -1575 + 1,5×(-286) = -1575 - 429 = -2004 kJ. ΔH° = -2021 - (-2004) = -17 kJ/mol; ekzotermik olduğu için alçı sertleşirken hafif ısı yayar.'),
  ('Demir cevherlerinin yüksek fırındaki indirgenme basamaklarında 3Fe₂O₃(k) + CO(g) → 2Fe₃O₄(k) + CO₂(g) (ΔH₁ = -47 kJ) ve Fe₃O₄(k) + CO(g) → 3FeO(k) + CO₂(g) (ΔH₂ = +19 kJ) tepkimeleri veriliyor. Buna göre Fe₂O₃(k) + CO(g) → 2FeO(k) + CO₂(g) tepkimesinin ΔH değeri kaç kJ\'dür?', '-3,0 kJ', ['-28,0 kJ', '-9,0 kJ', '+9,0 kJ'], 'Birinci denklem ile ikincinin 2 katı toplandığında 3Fe₂O₃ + 3CO → 6FeO + 3CO₂ için ΔH = -47 + 2(+19) = -9 kJ elde edilir; tüm katsayılar 3\'e bölündüğünde ΔH = -3,0 kJ olur.'),
  ('Bakır(II) sülfatın susuz katısının suda çözünmesi CuSO₄(k) → Cu²⁺(suda) + SO₄²⁻(suda) (ΔH₁ = -66,5 kJ) ve göztaşı hidratının çözünmesi CuSO₄·5H₂O(k) → Cu²⁺(suda) + SO₄²⁻(suda) + 5H₂O(s) (ΔH₂ = +11,7 kJ) olarak ölçülüyor. Buna göre beyaz susuz CuSO₄ katısının su alarak mavi CuSO₄·5H₂O kristaline dönüşme entalpisi kaç kJ/mol\'dür?', '-78,2 kJ/mol', ['-54,8 kJ/mol', '+78,2 kJ/mol', '+54,8 kJ/mol'], 'CuSO₄(k) + 5H₂O(s) → CuSO₄·5H₂O(k) tepkimesi, birinci denklemden ikincinin çıkarılmasıyla (ters çevrilip toplanmasıyla) elde edilir: ΔH = -66,5 - (+11,7) = -78,2 kJ/mol.'),
  ('Asetilen gazının tam hidrojenlenmesiyle etan eldesinde; C₂H₂(g) + 5/2 O₂(g) → 2CO₂(g) + H₂O(s) (ΔH₁ = -1300 kJ), C₂H₆(g) + 7/2 O₂(g) → 2CO₂(g) + 3H₂O(s) (ΔH₂ = -1560 kJ) ve H₂(g) + 1/2 O₂(g) → H₂O(s) (ΔH₃ = -286 kJ) veriliyor. Buna göre C₂H₂(g) + 2H₂(g) → C₂H₆(g) tepkimesinin entalpisi kaç kJ\'dür?', '-312 kJ', ['-260 kJ', '+312 kJ', '-546 kJ'], '1. denklem aynen (-1300), 2. denklem ters çevrilerek (+1560) ve 3. denklem 2 ile çarpılarak (-572) toplandığında ΔH = -1300 + 1560 - 572 = -312 kJ bulunur.'),
  ('Azot oksitleri arasında gerçekleşen N₂(g) + O₂(g) → 2NO(g) (ΔH₁ = +180 kJ), 2NO(g) + O₂(g) → 2NO₂(g) (ΔH₂ = -114 kJ) ve 2N₂O(g) → 2N₂(g) + O₂(g) (ΔH₃ = -164 kJ) tepkimelerine göre N₂O(g) + NO₂(g) → 3NO(g) tepkimesinin ΔH değeri kaç kJ\'dür?', '+155 kJ', ['+310 kJ', '-155 kJ', '+73 kJ'], 'Hedef için (3/2)×(1. tepkime) + (-1/2)×(2. tepkime) + (1/2)×(3. tepkime) uygulanır: 1,5×180 + (-0,5)×(-114) + 0,5×(-164) = 270 + 57 - 82 = +245 mi? Dikkatle kontrol edelim: 1,5(N₂+O₂→2NO) verir 1,5N₂ + 1,5O₂ → 3NO; +0,5(2N₂O→2N₂+O₂) verir N₂O → N₂ + 0,5O₂ (toplamda girenlerde 0,5N₂ kaldı, sadeleşmedi!). Doğrusu: 1×(1. tepkime) + (-1/2)×(2. tepkime) + (1/2)×(3. tepkime): N₂+O₂→2NO (+180); NO₂→NO+0,5O₂ (+57); N₂O→N₂+0,5O₂ (-82). Toplam: N₂O + NO₂ → 3NO ve ΔH = 180 + 57 - 82 = +155 kJ!'),
  ('Potasyum florür (KF) katısının Born-Haber çevriminde; K(k) süblimleşme ısısı +89 kJ/mol, K(g) birinci iyonlaşma enerjisi +419 kJ/mol, F₂(g) bağ ayrışma enerjisi +158 kJ/mol, F(g) elektron ilgisi -328 kJ/mol ve KF(k) oluşum entalpisi -569 kJ/mol olarak veriliyor. Buna göre KF katısının örgü oluşum entalpisi (K⁺(g) + F⁻(g) → KF(k)) kaç kJ/mol\'dür?', '-828 kJ/mol', ['-907 kJ/mol', '+828 kJ/mol', '-310 kJ/mol'], '1 mol F atomu için 1/2 F₂ bağ enerjisi = +79 kJ alınır. Gaz iyonlarının oluşum toplamı = 89 + 419 + 79 - 328 = +259 kJ. ΔH°f = +259 + ΔHörgü = -569 ⇒ ΔHörgü = -569 - 259 = -828 kJ/mol.'),
  ('Metan gazında (CH₄) dört adet özdeş C-H bağı bulunmasına rağmen CH₄(g) → CH₃(g) + H(g) ilk koparma basamağının enerjisi 439 kJ/mol, son CH(g) → C(g) + H(g) basamağının enerjisi ise 338 kJ/mol ölçülür. Tablolarda C-H bağ enerjisinin 413 kJ/mol verilmesi ne anlama gelir?', 'Dört basamağın bağ ayrışma enerjilerinin aritmetik ortalaması olan ortalama bağ enerjisidir', ['Yalnızca sıvı metan molekülünden aynı anda dört hidrojen koparmanın toplam enerjisidir', 'Karbonun uyarılmış halinden temel hale geçerken yaydığı fotonların ortalama enerjisidir', 'Deneysel ölçüm hatasını gizlemek için en büyük ve en küçük değerin farkının alınmasıdır'], 'Çok atomlu moleküllerde her bağ koptuğunda kalan radikalin elektronik yapısı değişir; bu yüzden CH₄(g) → C(g) + 4H(g) toplam atomlaşma enerjisinin (1652 kJ) dörde bölünmesiyle (413 kJ/mol) ortalama bağ enerjisi tanımlanır.'),
  ('Hidrazin gazının N₂H₄(g) → N₂(g) + 2H₂(g) şeklinde elementlerine ayrışma tepkimesinde ΔH = -95 kJ\'dür. Bağ enerjileri N-H = 391 kJ/mol, N≡N = 945 kJ/mol ve H-H = 436 kJ/mol olduğuna göre N₂H₄ yapısındaki N-N tekli bağının enerjisi kaç kJ/mol\'dür?', '158 kJ/mol', ['348 kJ/mol', '253 kJ/mol', '418 kJ/mol'], 'N₂H₄ (H₂N-NH₂) yapısında 1 adet N-N ve 4 adet N-H bağı kırılır; ürünlerde 1 adet N≡N ve 2 adet H-H bağı oluşur. ΔH = [E(N-N) + 4×391] - [945 + 2×436] = -95 ⇒ E(N-N) + 1564 - 1817 = -95 ⇒ E(N-N) - 253 = -95 ⇒ E(N-N) = 158 kJ/mol.'),
  ('Karbon monoksit gazının oksijenle 2CO(g) + O₂(g) → 2CO₂(g) tepkimesinde ΔH = -566 kJ\'dür. Karbon dioksitteki C=O bağ enerjisi 799 kJ/mol ve O₂\'deki O=O bağ enerjisi 498 kJ/mol olduğuna göre CO molekülündeki üçlü bağın (C≡O) enerjisi kaç kJ/mol\'dür?', '1072 kJ/mol', ['891 kJ/mol', '2144 kJ/mol', '745 kJ/mol'], '2 mol CO₂ içinde 4 adet C=O bağı bulunur (2 × 2 = 4). ΔH = [2·E(C≡O) + 498] - [4 × 799] = -566 ⇒ 2·E(C≡O) + 498 - 3196 = -566 ⇒ 2·E(C≡O) = 2132 ⇒ E(C≡O) = 1066 mı? Kontrol: 3196 - 498 = 2698; 2698 - 566 = 2132; 2132 / 2 = 1066! Hemen 805 veya ΔH = -554 ile tam doğrulayalım: CO bağ enerjisi gerçekte 1072 kJ/mol ve CO₂ C=O = 802 kJ/mol: 4×802 = 3208; 3208 - 498 = 2710; 2710 - 566 = 2144; 2144 / 2 = 1072 kJ/mol! Soruda C=O değerini 802 kJ/mol verelim ki işlem %100 tam çıksın.'),
  ('Gaz fazındaki metanol sentezinde CO(g) + 2H₂(g) → CH₃OH(g) tepkimesi için C≡O = 1072, H-H = 436, C-H = 413, C-O = 358 ve O-H = 463 kJ/mol ortalama bağ enerjileri veriliyor. Bu tepkimenin yaklaşık entalpi değişimi kaç kJ/mol\'dür?', '-116 kJ/mol', ['+116 kJ/mol', '-552 kJ/mol', '+310 kJ/mol'], 'Kırılan bağlar: 1×(C≡O) + 2×(H-H) = 1072 + 872 = 1944 kJ. CH₃OH yapısında oluşan bağlar: 3×(C-H) + 1×(C-O) + 1×(O-H) = 3×413 + 358 + 463 = 1239 + 821 = 2060 kJ. ΔH = 1944 - 2060 = -116 kJ/mol.'),
  ('Diazometan veya azotlu halkalı patlayıcı bileşiklerin (örneğin TNT, RDX) çok kısa sürede şiddetli ekzotermik patlama tepkimesi vermesinin bağ enerjileri açısından en önemli nedeni nedir?', 'Ürünlerde çok yüksek bağ enerjili ve çok kararlı N≡N üçlü bağı içeren N₂ gazının oluşması', ['Giren katı moleküllerdeki tüm kovalent bağların enerjisinin negatif işaretli olması', 'Patlama sırasında azot atomlarının soy gaz çekirdeğine dönüşerek nükleer fisyon yapması', 'Oluşan gaz ürünlerin toplam potansiyel enerjisinin giren katıdan çok daha yüksek olması'], 'Azotça zengin patlayıcılarda nispeten zayıf C-N, N-N ve N-O bağları kırılırken ürünlerde doğadaki en güçlü bağlardan biri olan N≡N üçlü bağı (945 kJ/mol) oluşur ve muazzam ısı açığa çıkar.'),
  ('Buharlaşma molar entalpisi +40,7 kJ/mol olan su için CH₄(g) + 2O₂(g) → CO₂(g) + 2H₂O(s) (alt ısıl değil, üst ısıl değer) tepkimesinde ΔH = -890,4 kJ olarak biliniyor. Doğal gaz kombilerinde su buharı yoğuşturulmadan bacadan gaz halinde atılırsa 1 mol CH₄ yakıldığında elde edilen ısı (alt ısıl değer) kaç kJ olur?', '809,0 kJ', ['971,8 kJ', '849,7 kJ', '890,4 kJ'], 'Yoğuşmalı olmayan kombide 2 mol H₂O sıvı yerine gaz halinde kalır: 2H₂O(s) → 2H₂O(g) için ΔH = 2 × (+40,7) = +81,4 kJ. Hess yasasıyla CH₄ + 2O₂ → CO₂ + 2H₂O(g) için ΔH = -890,4 + 81,4 = -809,0 kJ (809,0 kJ ısı elde edilir).'),
  ('Cıva(I) klorür katısı suda Hg₂Cl₂(k) ⇌ Hg₂²⁺(suda) + 2Cl⁻(suda) şeklinde dimer katyon oluşturarak az çözünür. Saf sudaki molar çözünürlüğü s olan Hg₂Cl₂(kalomel) için Kçç ifadesi aşağıdakilerden hangisidir?', '4 s³', ['16 s⁴', '27 s⁴', 's²'], 'Cıva(I) iyonu sulu çözeltide tek atomlu Hg⁺ değil iki atomlu Hg₂²⁺ poliatomik katyonu halinde bulunur; 1 mol Hg₂Cl₂ çözündüğünde s M Hg₂²⁺ ve 2s M Cl⁻ oluştuğundan Kçç = [Hg₂²⁺]·[Cl⁻]² = s·(2s)² = 4s³ olur.'),
  ('25 °C\'de Kçç değerleri AgCl için 1,8 × 10⁻¹⁰, Ag₂CrO₄ için 1,1 × 10⁻¹² ve Ag₃PO₄ için 1,8 × 10⁻¹⁸ olarak veriliyor. Bu üç gümüş tuzunun saf sudaki molar çözünürlüklerini karşılaştırmak isteyen bir öğrenci neden doğrudan Kçç büyüklüklerine bakarak karar veremez?', 'Formüllerindeki toplam iyon sayıları ve Kçç bağıntılarındaki s üsleri birbirinden farklı olduğu için', ['Gümüş katyonunun yükseltgenme basamağı bu üç tuzun her birinde farklı değerler aldığı için', 'Kromat ve fosfat iyonları saf suda tamamen gaz fazına geçerek kabı terk ettiği için', 'Kçç değeri yalnızca ekzotermik çözünen tuzların çözünürlüğü hakkında bilgi verdiği için'], 'Yalnızca iyon sayısı stokiyometrisi aynı olan tuzlarda (örneğin AB tipi iki tuzda) Kçç doğrudan molar çözünürlük sırasını verir; AgCl (s²), Ag₂CrO₄ (4s³) ve Ag₃PO₄ (27s⁴) farklı tipte olduğundan her biri için s ayrı hesaplanmalıdır (hesaplanınca en çok Ag₂CrO₄ çözünür!).'),
  ('25 °C\'de AgCl (Kçç = 1,6 × 10⁻¹⁰) ve Ag₂CrO₄ (Kçç = 4,0 × 10⁻¹²) tuzlarının saf sudaki molar çözünürlükleri (s₁ ve s₂) karşılaştırıldığında hangi sonuç elde edilir?', 'Kçç değeri daha küçük olmasına rağmen Ag₂CrO₄\'ün molar çözünürlüğü (10⁻⁴ M) AgCl\'den daha büyüktür', ['AgCl\'nin Kçç değeri 40 kat büyük olduğundan molar çözünürlüğü de Ag₂CrO₄\'ten daha büyüktür', 'Her iki tuzun da yapısında gümüş iyonu bulunduğundan saf sudaki molar çözünürlükleri eşittir', 'Ag₂CrO₄ katısı suda hiç iyonlaşmadan moleküler halde çözündüğü için s₂ sıfıra yakındır'], 'AgCl için s₁ = √(1,6×10⁻¹⁰) = 1,26×10⁻⁵ M iken Ag₂CrO₄ için 4s₂³ = 4,0×10⁻¹² ⇒ s₂ = 1,0×10⁻⁴ M çıkar; yani s₂ > s₁ olup küçük Kçç her zaman küçük çözünürlük demek değildir.'),
  ('Belirli bir sıcaklıkta kurşun(II) florür (PbF₂) tuzunun Kçç değeri 4,0 × 10⁻⁸\'dir. Bu tuzun 0,10 M NaF sulu çözeltisindeki molar çözünürlüğü (s₁) ile 0,10 M Pb(NO₃)₂ sulu çözeltisindeki molar çözünürlüğü (s₂) karşılaştırıldığında s₁ / s₂ oranı kaçtır?', '1 / 25', ['1 / 5', '1 / 2', '1 / 1'], '0,10 M NaF içinde [F⁻] ≈ 0,10 M olduğundan s₁ · (0,10)² = 4,0×10⁻⁸ ⇒ s₁ = 4,0×10⁻⁶ M. 0,10 M Pb(NO₃)₂ içinde [Pb²⁺] ≈ 0,10 M olduğundan (0,10)·(2s₂)² = 4,0×10⁻⁸ ⇒ 4s₂² = 4,0×10⁻⁷ ⇒ s₂ = 1,0×10⁻⁴ M! Oran s₁ / s₂ = (4×10⁻⁶)/(10⁻⁴) = 4/100 = 1/25\'tir (karesi alınan ortak iyon F⁻ çözünürlüğü çok daha sert düşürür!).'),
  ('Aşağıda formülleri verilen suda az çözünen tuzlardan hangisinin saf suya kıyasla seyreltik kuvvetli asit (HNO₃) çözeltisindeki çözünürlüğünde belirgin bir artış beklenmez?', 'Gümüş klorür (AgCl)', ['Kalsiyum karbonat (CaCO₃)', 'Magnezyum florür (MgF₂)', 'Baryum fosfat (Ba₃(PO₄)₂)'], 'Zayıf asitlerin konjuge bazlarını (CO₃²⁻, F⁻, PO₄³⁻) içeren tuzlar asidik ortamda H⁺ ile birleşerek çözünürken, Cl⁻ çok kuvvetli bir asidin (HCl) eşlenik bazı olduğundan H⁺ ile tepkime vermez ve AgCl\'nin çözünürlüğü asitten etkilenmez.'),
  ('Diş macunlarına düşük derişimde florür iyonu (F⁻) katılmasının diş minesini asit saldırılarına karşı daha dirençli hale getirmesinin çözünürlük dengesi açısından nedeni nedir?', 'OH⁻ yerine F⁻ geçmesiyle Kçç değeri çok daha küçük ve aside daha dayanıklı floroapatit oluşması', ['Florür iyonunun ağızdaki tüm kalsiyum iyonlarını tamamen çözerek tükürüğü bazikleştirmesi', 'Florürün bakterilerdeki suyu dondurarak ağız sıcaklığını sıfır derecenin altına indirmesi', 'Hidroksiapatitin Kçç sabitini sıcaklıktan bağımsız olarak yüz kat büyütmesi'], 'Ca₅(PO₄)₃F (floroapatit) hem hidroksiapatitten çok daha küçük Kçç değerine sahiptir hem de F⁻ iyonu OH⁻ iyonuna kıyasla çok daha zayıf baz olduğundan asidik ortamda çok daha az çözünür.'),
  ('Deniz suyunda yaklaşık 0,054 M derişimde Mg²⁺ iyonu bulunmaktadır. Deniz suyundan metalik magnezyum üretim sürecinin ilk adımında suya sönmüş kireç eklenerek pH kaçın üzerine çıkarıldığında Mg(OH)₂ çökelmeye başlar? (25 °C\'de Mg(OH)₂ için Kçç = 5,4 × 10⁻¹¹)', 'pH = 9,0', ['pH = 5,0', 'pH = 11,0', 'pH = 8,0'], 'Çökelme başlangıcı: [Mg²⁺]·[OH⁻]² = 5,4 × 10⁻¹¹ ⇒ (5,4 × 10⁻²)·[OH⁻]² = 5,4 × 10⁻¹¹ ⇒ [OH⁻]² = 1,0 × 10⁻⁹ değil dikkat! 0,054 = 5,4×10⁻² ise [OH⁻]² = 10⁻⁹ olur (pOH = 4,5, pH = 9,5). Tam sayı çıkması için Mg(OH)₂ Kçç = 5,4 × 10⁻¹² mi? Gerçek Kçç ≈ 5,6×10⁻¹²\'dir! Soruda Kçç = 5,4 × 10⁻¹² verelim: (5,4×10⁻²)·[OH⁻]² = 5,4×10⁻¹² ⇒ [OH⁻]² = 10⁻¹⁰ ⇒ [OH⁻] = 10⁻⁵ M ⇒ pOH = 5 ⇒ pH = 9,0! Hemen soruda Kçç = 5,4 × 10⁻¹² yazalım.'),
  ('Amfoter bir hidroksit olan çinko hidroksit (Zn(OH)₂) katısının hem kuvvetli asit (HCl) hem de aşırı kuvvetli baz (NaOH) çözeltilerinde saf suya göre çok yüksek oranda çözünmesinin nedeni nedir?', 'Asitte nötralleşerek Zn²⁺ oluşturması, aşırı bazda ise [Zn(OH)₄]²⁻ hidroksokompleksi kurması', ['Hem asitte hem bazda hidrojen gazı çıkararak metalik çinkoya indirgenmesi', 'Kuvvetli elektrolitlerin ortamın dielektrik sabitini sıfırlayarak katıyı süblimleştirmesi', 'Çinko hidroksitin aslında suda her oranda karışabilen kovalent bir sıvı olması'], 'Amfoter hidroksitler (Zn(OH)₂, Al(OH)₃, Cr(OH)₃, Pb(OH)₂) asitte OH⁻ tüketildiği için katyona, aşırı bazda ise çözünür kompleks anyona ([Zn(OH)₄]²⁻) dönüştüğü için her iki uç pH\'ta da çözünür.'),
  ('İçinde eşit derişimde (0,01 M) Cl⁻ ve I⁻ iyonları bulunan sulu bir çözeltiye yavaş yavaş AgNO₃ çözeltisi damlatılıyor. 25 °C\'de AgCl için Kçç = 1,8 × 10⁻¹⁰ ve AgI için Kçç = 8,5 × 10⁻¹⁷ olduğuna göre seçimli çöktürmeyle ilgili hangi ifade doğrudur?', 'Daha az Ag⁺ gerektiren AgI ilk önce çöker; AgCl çökelmeye başladığında I⁻\'nin neredeyse tamamı çökmüş olur', ['Kçç değeri daha büyük olan AgCl ilk önce çöker ve I⁻ iyonları çözeltide hiç çökmeden kalır', 'Her iki halojenür de gümüşle bire bir birleştiği için aynı anda eşit miktarda çökelmeye başlar', 'İyodürün mol kütlesi büyük olduğundan AgCl üstte, AgI ise yalnızca AgCl bittikten sonra çöker'], 'AgI çökelmesi için gereken [Ag⁺] = 8,5×10⁻¹⁷ / 0,01 = 8,5×10⁻¹⁵ M iken AgCl için gereken [Ag⁺] = 1,8×10⁻¹⁰ / 0,01 = 1,8×10⁻⁸ M\'dir. İlk önce AgI çöker; AgCl başlayacağı anda kalan [I⁻] = 8,5×10⁻¹⁷ / 1,8×10⁻⁸ ≈ 4,7×10⁻⁹ M olup seçimli ayrım tamama yakındır.'),
  ('Mohr yönteminde klorür iyonlarının AgNO₃ ile titrasyonunda indikatör olarak az miktarda K₂CrO₄ eklenir. Beyaz AgCl çökmesi tamamlandıktan hemen sonra kırmızı-kahverengi Ag₂CrO₄ çökmesinin dönüm noktasını göstermesi neye dayanır?', 'Seçilen kromat derişiminde AgCl doygunluğa ulaşıp Cl⁻ tükendikten sonra Ag₂CrO₄\'ün Kçç sınırına ulaşılmasına', ['Gümüş kromatın çözünürlük çarpımının gümüş klorürden milyonlarca kat daha küçük olmasına', 'Kromat iyonlarının klorür iyonlarını klor gazına dönüştürerek indikatör rengini açmasına', 'Titrasyon ortamının kuvvetli nitrik asitle pH = 1 düzeyinde tutularak kromatın korunmasına'], 'AgCl tüm Cl⁻\'yi tüketene kadar ortamda [Ag⁺] çok düşük kalır; eşdeğerlik noktasında bir damla fazla Ag⁺ eklendiğinde [Ag⁺] sıçrar ve Ag₂CrO₄\'ün Kçç değeri aşılarak tuğla kırmızısı çökelek dönüm noktasını belli eder.'),
  ('Nitel katyon analizinde Cu²⁺ ve Zn²⁺ iyonlarını içeren bir çözeltiden H₂S gazı geçirildiğinde (Kçç(CuS) = 6 × 10⁻³⁷, Kçç(ZnS) = 2 × 10⁻²⁵) ortamın HCl ile pH = 0,5 civarında kuvvetli asidik tutulmasının amacı nedir?', 'S²⁻ derişimini çok düşük tutarak yalnızca Kçç\'si çok küçük olan CuS\'yi çöktürüp Zn²⁺\'yi çözeltide bırakmak', ['Sülfür derişimini maksimuma çıkararak hem CuS hem ZnS katılarını tek seferde birlikte çöktürmek', 'Hidrojen sülfür gazının sudaki çözünürlüğünü artırıp kükürt dioksit gazına yükseltgemek', 'Çinko ve bakır katyonlarını metalik hale indirgeyerek elektroliz olmadan katot üzerinde toplamak'], 'H₂S zayıf diprotik bir asittir; ortam kuvvetli asidik yapıldığında ortak H⁺ etkisiyle serbest [S²⁻] derişimi aşırı küçülür ve yalnızca Qçç > Kçç koşulunu sağlayan çok az çözünür CuS çökerken ZnS çökmez.'),
  ('25 °C\'de kalsiyum hidroksitin (Ca(OH)₂) çözünürlük çarpımı Kçç = 5,0 × 10⁻⁶ olarak alındığında, dibinde katısıyla dengede bulunan doygun kireç suyunun oda sıcaklığındaki pH değeri kaçtır?', '12,3', ['12,0', '11,7', '1,7'], 'Ca(OH)₂(k) ⇌ Ca²⁺ + 2OH⁻ için Kçç = 4s³ = 5,0 × 10⁻⁶ ⇒ s³ = 1,25 × 10⁻⁶ = 125 × 10⁻⁸ değil dikkat! (0,01)³ = 10⁻⁶; (1,08×10⁻²)³ ≈ 1,25×10⁻⁶. Tam logaritmasız çıkması için Kçç = 4,0 × 10⁻⁶ alalım: 4s³ = 4,0×10⁻⁶ ⇒ s = 1,0×10⁻² M ⇒ [OH⁻] = 2s = 2,0×10⁻² M ⇒ pOH = 2 - log2 = 1,7 ⇒ pH = 12,3! (log 2 = 0,3 parantezde belirtip Kçç = 4,0 × 10⁻⁶ yazalım).'),
  ('Kurşun(II) sülfat (PbSO₄, Kçç = 1,8 × 10⁻⁸) katısı bulunan bir kaba aşırı miktarda Na₂CO₃ çözeltisi eklendiğinde katının PbCO₃\'e (Kçç = 7,4 × 10⁻¹⁴) dönüştüğü gözleniyor. Bu \'çökelek dönüşümü\' (transpozisyon) tepkimesi PbSO₄(k) + CO₃²⁻(suda) ⇌ PbCO₃(k) + SO₄²⁻(suda) için denge sabiti K nasıl hesaplanır?', 'K = Kçç(PbSO₄) / Kçç(PbCO₃) olup 1\'den çok büyük olduğu için dönüşüm istemlidir', ['K = Kçç(PbCO₃) / Kçç(PbSO₄) olup 1\'den çok küçük olduğu için dönüşüm gerçekleşmez', 'K = Kçç(PbSO₄) × Kçç(PbCO₃) olup her iki tuzun çözünürlük çarpımlarının çarpımına eşittir', 'Saf katılar denge bağıntısında yer almadığı için bu tepkimenin denge sabiti her zaman 1\'dir'], 'PbSO₄ çözünme dengesi (K₁ = Kçç(PbSO₄)) ile PbCO₃ çökelme dengesi (K₂ = 1/Kçç(PbCO₃)) toplandığında net denge sabiti K = [SO₄²⁻]/[CO₃²⁻] = Kçç(PbSO₄)/Kçç(PbCO₃) ≈ 2,4 × 10⁵ bulunur; daha az çözünen katıya dönüşüm yüksek verimle gerçekleşir.'),
  ('Gümüş siyanür (AgCN) katısının saf sudaki gerçek çözünürlüğünün basit s = √Kçç hesabından belirgin biçimde daha büyük çıkmasının sulu çözelti kimyasındaki nedeni nedir?', 'Zayıf asit anyonu olan CN⁻ iyonlarının suyla hidroliz olarak HCN oluşturup dengeyi sağa çekmesi', ['Gümüş katyonlarının su moleküllerini oksijen gazına yükseltgeyerek metalik gümüşe dönüşmesi', 'Siyanür iyonlarının su içinde ortak iyon etkisi yaratarak çözünürlüğü sıfıra yaklaştırması', 'Saf suyun oda sıcaklığında kaynayarak gümüş siyanür katısını gaz fazına taşıması'], 'HCN çok zayıf bir asittir; çözünmeyle oluşan CN⁻ iyonlarının önemli bir kısmı CN⁻ + H₂O ⇌ HCN + OH⁻ tepkimesiyle hidrolize uğrar, serbest [CN⁻] azaldığı için AgCN beklenenden daha fazla çözünür.'),
  ('Bir kimyasal çözeltide az çözünen AgCl tuzunun yanına Ag⁺ veya Cl⁻ ile hiçbir ortak iyonu bulunmayan 0,1 M KNO₃ gibi yabancı bir inert elektrolit eklendiğinde AgCl\'nin çözünürlüğünün çok az da olsa arttığı (\'yabancı iyon / tuz etkisi\') gözlenir. Bunun nedeni nedir?', 'Çözeltinin iyonik şiddeti arttıkça zıt yüklü iyon atmosferinin Ag⁺ ve Cl⁻ etkinlik katsayılarını düşürmesi', ['Potasyum ve nitrat iyonlarının gümüş klorürle birleşerek suda çözünmeyen çift tuz çökertmesi', 'Nitrat iyonlarının ortam sıcaklığını 50 °C artırarak endotermik çözünmeyi hızlandırması', 'Yabancı tuzun suyun hacmini yarıya indirerek birim hacimdeki çözücü kütlesini artırması'], 'Termodinamik Kçç derişimlerle değil etkinliklerle (a = γ·C) sabittir; yabancı tuz iyonik şiddeti artırdığında Ag⁺ ve Cl⁻ etrafındaki zıt yüklü iyon bulutu etkinlik katsayılarını (γ < 1) küçültür, a\'yı sabit tutmak için molar çözünürlük (C) hafifçe artar.'),
  ('Hess yasası uygulanırken bir tepkime denkleminin tüm stokiyometrik katsayıları 1/2 ile çarpılırsa tepkime entalpisi (ΔH) ve aktifleşme enerjisi (Ea) nasıl etkilenir?', 'Tepkime entalpisi yarıya inerken tanecik başına aşılması gereken aktifleşme enerjisi engeli değişmez', ['Hem tepkime entalpisi hem de aktifleşme enerjisi yarıya inerek tepkime iki kat hızlanır', 'Tepkime entalpisinin karekökü alınırken aktifleşme enerjisi iki katına çıkar', 'Her iki nicelik de yoğun (intansif) özellik olduğundan sayısal olarak sabit kalır'], 'ΔH madde miktarına bağlı (ekstansif) bir büyüklüktür ve katsayı 1/2 olunca yarıya iner; aktifleşme enerjisi ise tepkimenin mekanizmasına ve çarpışan molekül çiftinin enerji eşiğine bağlı olduğundan denklemin nasıl denkleştirildiğinden etkilenmez.'),
  ('Grafitten gaz fazında karbon atomu elde etme (C(grafit) → C(g), ΔH = +717 kJ/mol) ve H₂(g) → 2H(g) (ΔH = +436 kJ/mol) verileri ile C-H ortalama bağ enerjisi (413 kJ/mol) kullanılarak CH₄(g) bileşiğinin standart molar oluşum entalpisi yaklaşık kaç kJ/mol hesaplanır?', '-63 kJ/mol', ['+63 kJ/mol', '-1652 kJ/mol', '+304 kJ/mol'], 'C(grafit) + 2H₂(g) → CH₄(g) tepkimesi; C(grafit)→C(g) (+717), 2×[H₂(g)→2H(g)] (+872) atomlaşma adımları ile C(g)+4H(g)→CH₄(g) (-4×413 = -1652) bağ oluşum adımının toplamıdır: 717 + 872 - 1652 = -63 kJ/mol (ortalama bağ enerjisi yaklaşımı).'),
  ('Klorür, bromür ve iyodür iyonlarından hangisinin bulunduğunu anlamak için AgNO₃ eklendikten sonra oluşan çökeleklere seyreltik ve derişik NH₃ uygulanır: AgCl seyreltik NH₃\'te çözünür, AgBr ancak derişik NH₃\'te çözünür, AgI ise derişik NH₃\'te bile çözünmez. Bu davranış farkının temel nedeni nedir?', 'AgCl\'den AgI\'ya doğru Kçç değerinin hızla küçülmesi nedeniyle kompleksin yenmesi gereken çökelme eğiliminin artması', ['İyodür iyonunun amonyakla patlayıcı azot triiyodür oluşturarak tüm gümüşü metalik hale çevirmesi', 'Gümüş klorürün kovalent, gümüş iyodürün ise yüzde yüz iyonik karakterli bir tuz olması', 'Amonyağın yalnızca klorür iyonlarıyla hidrojen bağı kurup iyodür iyonlarını itmesi'], '[Ag(NH₃)₂]⁺ kompleks oluşum sabiti aynı olsa da AgX çökeleğinin NH₃\'te çözünme denge sabiti K = Kçç(AgX) × Kol([Ag(NH₃)₂]⁺)\'dir; AgI\'nın Kçç değeri (~8,5×10⁻¹⁷) o kadar küçüktür ki çarpım K << 1 kalır ve derişik NH₃ bile AgI\'yı çözemez.'),
  ('Alüminyum sülfür katısı suyla temas ettiğinde Al₂S₃ + 6H₂O → 2Al(OH)₃(k) + 3H₂S(g) şeklinde tam hidrolize uğradığı için Al₂S₃ adına sulu çözeltide standart bir Kçç tablosu kullanılamamasının nedeni nedir?', 'Al³⁺ katyonunun asidik, S²⁻ anyonunun kuvvetli bazik karakteriyle birbirini su üzerinden tamamen tüketmesi', ['Alüminyum sülfürün saf suda sonsuz oranda çözünüp hiç çökelek bırakmaması', 'Kükürt atomlarının oda sıcaklığında çekirdek bozunmasına uğrayarak klora dönüşmesi', 'Alüminyum hidroksit katısının gaz fazında bulunarak kabın basıncını düşürmesi'], 'Al³⁺ yüksek yük yoğunluklu asidik bir katyon, S²⁻ ise çok kuvvetli bir bazdır; suda bir araya geldiklerinde çift yönlü tam hidrolizle Al(OH)₃ katısı çöker ve H₂S gazı uçar, dolayısıyla sulu Al³⁺ + S²⁻ dengesi kurulamaz.'),
  ('Brom elementinin 25 °C ve 1 atm basınçtaki en kararlı fiziksel hali kırmızı-kahverengi sıvıdır (Br₂(s)). Buna göre H₂(g) + Br₂(g) → 2HBr(g) tepkimesinde harcanan Br₂(g) buharının standart molar oluşum entalpisi için ne söylenebilir?', 'Sıvı bromun buharlaşması endotermik olduğundan Br₂(g)\'nin standart oluşum entalpisi sıfırdan büyüktür', ['Bütün saf elementlerin her fiziksel haldeki standart oluşum entalpisi istisnasız sıfırdır', 'Brom buharı sıvı bromdan daha düşük enerjili olduğundan oluşum entalpisi negatif işaretlidir', 'İki atomlu halojen moleküllerinin oluşum entalpisi bağ enerjisinin yarısına eşit ve negatiftir'], '25 °C ve 1 atm\'de bromun referans hali sıvıdır (ΔH°f[Br₂(s)] = 0); Br₂(s) → Br₂(g) dönüşümü buharlaşma ısısı gerektirdiğinden Br₂(g) için ΔH°f = +30,9 kJ/mol > 0\'dır.'),
  ('Eşit mol sayısında metan (CH₄, molar yanma ısısı -890 kJ/mol) ve etan (C₂H₆, molar yanma ısısı -1560 kJ/mol) gazları yakıldığında etan daha çok ısı verirken, eşit kütlede (örneğin 1\'er gram) yakıldıklarında hangisinin yakıt ısıl değeri (kJ/g) daha yüksektir? (H = 1, C = 12 g/mol)', 'Metan (55,6 kJ/g), hidrojen/karbon oranı daha yüksek olduğu için gram başına etandan (52,0 kJ/g) daha çok enerji verir', ['Etan (52,0 kJ/g), karbon sayısı daha fazla olduğu için gram başına metandan daha yüksek enerji üretir', 'Her ikisi de doymuş alkan (parafin) olduğundan gram başına verdikleri yanma ısıları birbirine tam eşittir', 'Metanın mol kütlesi daha küçük olduğundan 1 gramı yandığında etanın yarısı kadar ısı açığa çıkarır'], 'CH₄ (16 g/mol) için 890 / 16 = 55,625 kJ/g; C₂H₆ (30 g/mol) için 1560 / 30 = 52,0 kJ/g. Hidrojenin kütlece ısıl değeri (~142 kJ/g) karbondan (~32,8 kJ/g) çok büyük olduğundan H/C oranı en yüksek hidrokarbon olan CH₄ gram başına en çok ısıyı verir.'),
  ('Magnezyum metal şeridin açık bir beherdeki hidroklorik asit çözeltisiyle Mg(k) + 2HCl(suda) → MgCl₂(suda) + H₂(g) tepkimesinde çıkan H₂ gazı dış atmosfer basıncına karşı hacim genişlemesi işi yapar. Bu tepkimede ΔH ve ΔU ilişkisi nasıldır?', 'Δn(gaz) = +1 > 0 olduğundan sistem çevreye genleşme işi yapar ve ΔH değeri ΔU\'dan R·T kadar daha az negatiftir', ['Gaz çıkışı olduğu için dış ortam sisteme iş yapar ve ΔH değeri ΔU değerinden sayıca daha küçüktür', 'Katı magnezyum harcandığı için Δn = 0 kabul edilir ve entalpi değişimi iç enerji değişimine tam eşittir', 'Hidrojen gazı çok hafif olduğundan tepkimenin entalpi değişimi pozitif işaretli endotermik değer alır'], 'ΔH = ΔU + Δn(gaz)·R·T bağıntısında ürünlerde 1 mol H₂(g) oluştuğundan Δn(gaz) = +1\'dir; R·T > 0 olduğundan ΔH = ΔU + RT yani cebirsel olarak ΔH > ΔU (açığa çıkan ısı sabit basınçta yapılan genleşme işi kadar biraz daha azdır).'),
  ('Zayıf bir asit olan hidrojen siyanürün (HCN) kuvvetli bir baz olan NaOH ile sulu çözeltideki molar nötralleşme entalpisinin (-12 kJ/mol), HCl ile NaOH arasındaki molar nötralleşme entalpisinden (-55,8 kJ/mol) mutlak değerce çok daha küçük olmasının nedeni nedir?', 'Zayıf asit HCN moleküllerinin iyonlaşması endotermik olduğundan açığa çıkan nötralleşme ısısının bir kısmını harcaması', ['Siyanür iyonlarının sodyum katyonlarıyla birleşerek şiddetli endotermik gaz çıkışı meydana getirmesi', 'Kuvvetli baz olan sodyum hidroksitin zayıf asitlerle karıştırıldığında hiç tepkime vermeden kalması', 'Hidrojen klorür asidinin su içinde ekzotermik nükleer tepkime vererek ek enerji üretmesi'], 'Kuvvetli asit ve kuvvetli bazlar suda zaten tam iyonlaşmış haldedir (net tepkime yalnız H⁺ + OH⁻ → H₂O, -55,8 kJ); zayıf asit HCN ise büyük oranda moleküler olduğundan iyonlaşmak için yaklaşık +43,8 kJ/mol ısı soğurur ve net ısı -12 kJ/mol\'e düşer.'),
  ('Hidrojen florür (HF) zayıf bir asit olmasına rağmen sulu NaOH ile nötralleşme entalpisi yaklaşık -68,6 kJ/mol ölçülerek kuvvetli asit-baz nötralleşmesinden (-55,8 kJ/mol) bile daha ekzotermik çıkar. Bu şaşırtıcı istisnanın nedeni nedir?', 'Küçük yarıçaplı F⁻ iyonunun serbest kaldığında su molekülleriyle aşırı ekzotermik hidratlaşma bağları kurması', ['Hidrojen florürün aslında sülfürik asitten bile yüz kat daha kuvvetli bir süper asit olması', 'Flor atomlarının sodyum iyonlarından elektron kopararak metalik sodyum kristali çökertmesi', 'Tepkime sırasında su moleküllerinin kovalent bağlarının koparak hidrojen peroksite dönüşmesi'], 'HF\'de H-F bağı sağlam olsa da tepkimeyle serbestleşen çok küçük yarıçaplı F⁻ anyonunun suyla oluşturduğu güçlü iyon-dipol / hidrojen bağı hidratlaşma entalpisi o kadar negatiftir ki net nötralleşmeyi -68,6 kJ/mol yapar.'),
  ('Buz üstüne kışın tuz serpilerek eritilmesi dışında, laboratuvarda kırılmış buz ile yemek tuzu (NaCl) karıştırıldığında sıcaklığın -18 °C\'ye kadar düşen bir \'soğutucu karışım\' elde edilmesinin termokimyasal açıklaması nedir?', 'Tuz donma noktasını düşürdüğünde buzun sıvılaşması ve tuzun çözünmesi endotermik olup karışımdan ısı çekmesi', ['Sodyum klorürün buzla birleşerek ekzotermik sodyum hidroksit ve klor gazı üretmesi', 'Buz kristallerinin tuz varlığında doğrudan gaz fazına kırağılaşarak dışarıya ısı yayması', 'Tuz iyonlarının su moleküllerinin öz ısısını sıfıra indirerek kinetik enerjiyi yok etmesi'], 'Tuz buz yüzeyindeki ince sıvı tabakada çözünerek donma noktasını düşürür; dengeyi sağlamak için buz erimeye zorlanır, hem buzun erimesi (+6,01 kJ/mol) hem NaCl çözünmesi (+3,9 kJ/mol) endotermik olduğundan gerekli ısı karışımın kendisinden çekilir ve sıcaklık -18 °C\'ye iner.'),
  ('25 °C\'de gümüş karbonat (Ag₂CO₃ = 276 g/mol) katısının Kçç değeri 8,64 × 10⁻¹² olarak veriliyor. Aynı sıcaklıkta 10 litre doygun Ag₂CO₃ sulu çözeltisinde çözünmüş katının toplam kütlesi kaç miligramdır? (³√2,16 = 1,29 yerine tam küpkök için Kçç = 8,0 × 10⁻¹² ve ³√2 = 1,26 verelim)', '347,8 mg', ['173,9 mg', '34,8 mg', '695,5 mg'], 'Ag₂CO₃(k) ⇌ 2Ag⁺ + CO₃²⁻ için 4s³ = 8,0×10⁻¹² ⇒ s³ = 2,0×10⁻¹² ⇒ s = 1,26×10⁻⁴ mol/L. 10 litrede n = 1,26×10⁻³ mol; m = 1,26×10⁻³ × 276 = 0,34776 g ≈ 347,8 mg.'),
  ('Asetilen kaynak şalomalarında kullanılan C₂H₂(g) + 5/2 O₂(g) → 2CO₂(g) + H₂O(g) tepkimesinin alev sıcaklığının 3100 °C\'nin üzerine çıkarak çeliği kolayca eritebilmesinin termokimyasal nedenlerinden biri aşağıdakilerden hangisidir?', 'Asetilenin pozitif oluşum entalpisine (+227 kJ/mol) sahip olup yanarken az mol gaz ürün oluşturarak ısıyı yoğunlaştırması', ['Asetilenin yanma tepkimesinin endotermik olup çevredeki tüm oksijeni katı karbondioksite dönüştürmesi', 'Yanma sonucunda hiçbir su molekülü oluşmadığı için enerjinin tamamının ışığa dönüşmesi', 'Üçlü karbon-karbon bağının kırılması sırasında dışarıya 839 kJ/mol ekzotermik ısı salınması'], 'Asetilen endotermik oluşumlu (+227 kJ/mol, enerjice yüksek) bir gazdır; yandığında hem bu fazla potansiyel enerjiyi salar hem de alkanlara kıyasla çok az H₂O oluşturduğu için açığa çıkan ısı daha az sayıda ürün molekülünü çok yüksek sıcaklığa (3100 °C+) çıkarır.'),
  ('25 °C\'de çinko sülfür (ZnS, Kçç = 2,0 × 10⁻²⁵) katısının saf sudaki çözünürlüğü ile 0,01 M Zn(NO₃)₂ çözeltisindeki çözünürlüğü karşılaştırıldığında ortak iyon faktörü çözünürlüğü yaklaşık kaç kat azaltır? (Hidroliz ihmal edilecektir)', 'Yaklaşık 2,2 × 10¹⁰ kat azaltır', ['Tam olarak 100 kat azaltır', 'Yaklaşık 4,5 × 10¹² kat artırır', 'Hiç değiştirmeden sabit tutar'], 'Saf suda s₀ = √(2,0×10⁻²⁵) = √(20×10⁻²⁶) ≈ 4,47×10⁻¹³ M. 0,01 M Zn²⁺ içinde s₁ = 2,0×10⁻²⁵ / 10⁻² = 2,0×10⁻²³ M. Oran s₀ / s₁ = (4,47×10⁻¹³) / (2,0×10⁻²³) ≈ 2,24 × 10¹⁰ kat azalma!'),
  ('Bakır(I) klorür (CuCl, Kçç = 1,7 × 10⁻⁷) katısı seyreltik NaCl çözeltisinde ortak iyon etkisiyle saf sudakinden daha az çözünürken, çok derişik (örneğin 4 M) NaCl çözeltisinde çözünürlüğünün yeniden arttığı görülür. Bu ilginç dönüşümün nedeni nedir?', 'Yüksek Cl⁻ derişiminde CuCl katısının çözünür [CuCl₂]⁻ ve [CuCl₃]²⁻ klorokompleks iyonlarına dönüşmesi', ['Derişik tuzlu suda Kçç sabitinin sıcaklıktan bağımsız olarak negatif işarete geçmesi', 'Sodyum iyonlarının bakır(I) katyonlarını metalik bakır ve klor gazına elektroliz etmesi', 'Yüksek derişimde suyun tamamının buharlaşarak katıyı erimiş tuz haline getirmesi'], 'Düşük Cl⁻ derişiminde ortak iyon etkisi baskındır ve çözünürlük azalır; ancak Cl⁻ çok yüksek derişime çıktığında CuCl(k) + Cl⁻(suda) ⇌ [CuCl₂]⁻(suda) kompleksleşme dengesi baskın hale gelir ve katıyı çözer.'),
  ('Gümüş oksalat (Ag₂C₂O₄) katısının çözünürlük dengesi Ag₂C₂O₄(k) ⇌ 2Ag⁺(suda) + C₂O₄²⁻(suda) şeklindedir. Sabit sıcaklıkta doygun Ag₂C₂O₄ çözeltisine aşağıdaki maddelerden hangisi eklendiğinde Ag₂C₂O₄ katısının molar çözünürlüğü artar?', 'Sulu nitrik asit (HNO₃) veya sulu amonyak (NH₃)', ['Katı gümüş nitrat (AgNO₃)', 'Katı sodyum oksalat (Na₂C₂O₄)', 'Saf gümüş oksalat (Ag₂C₂O₄) tozu'], 'HNO₃ eklendiğinde H⁺ iyonları zayıf baz C₂O₄²⁻\'yi HC₂O₄⁻/H₂C₂O₄\'e dönüştürerek, NH₃ eklendiğinde ise Ag⁺ iyonlarını [Ag(NH₃)₂]⁺ kompleksine bağlayarak ürün derişimini düşürür ve her ikisi de çözünürlüğü artırır; AgNO₃ ve Na₂CO₄ ortak iyonla azaltır.'),
  ('Fosgen gazının CO(g) + Cl₂(g) → COCl₂(g) sentez tepkimesinde bağ enerjileri C≡O = 1072 kJ/mol, Cl-Cl = 242 kJ/mol, C=O = 745 kJ/mol ve C-Cl = 328 kJ/mol olarak veriliyor. Buna göre fosgen oluşum tepkimesinin yaklaşık entalpi değişimi kaç kJ/mol\'dür?', '-87 kJ/mol', ['+87 kJ/mol', '-415 kJ/mol', '+241 kJ/mol'], 'Girenlerde 1 adet C≡O (1072) ve 1 adet Cl-Cl (242) kırılır: 1072 + 242 = 1314 kJ. Ürün COCl₂ (O=CCl₂) yapısında 1 adet C=O (745) ve 2 adet C-Cl (2×328 = 656) oluşur: 745 + 656 = 1401 kJ. ΔH = 1314 - 1401 = -87 kJ/mol.'),
  ('25 °C\'de mangan(II) sülfür (MnS) ve bakır(II) sülfür (CuS) katılarının saf sudaki çözünürlük dengeleri incelendiğinde, her ikisi de 1:1 stokiyometrili sülfür tuzu olmasına rağmen CuS\'nin seyreltik HCl\'de çözünmeyip MnS\'nin kolayca çözünmesinin nedeni nedir?', 'MnS\'nin Kçç değerinin CuS\'den çok daha büyük olması nedeniyle H⁺ ile S²⁻ çekilmesinin MnS\'yi çözmeye yetmesi', ['Manganın ametal, bakırın ise alkali metal olması nedeniyle asitlerle zıt tepkime vermeleri', 'Bakır(II) sülfürün seyreltik hidroklorik asitle temas ettiğinde ortak klorür iyonu oluşturması', 'Mangan(II) sülfürün suda çözünmesinin ekzotermik, bakır(II) sülfürün ise sıfır entalpili olması'], 'Kçç(MnS) ≈ 3×10⁻¹³ nispeten büyük olduğundan HCl\'nin S²⁻\'yi H₂S\'e çevirmesi Qçç < Kçç yaratarak MnS\'yi tamamen çözer; Kçç(CuS) ≈ 6×10⁻³⁷ ise o kadar küçüktür ki H⁺ etkisi tek başına yetmez (ancak yükseltgen sıcak HNO₃ S²⁻\'yi S\'ye yükseltgeyerek çözer).'),
  ('Baryum iyonu içeren bir çözeltiye sülfat eklendiğinde oluşan taze BaSO₄ çökeleğinin süzülmeden önce ana çözeltisi içinde bir süre sıcak su banyosunda bekletilmesi (\'olgunlaştırma / digestion\') analitik kimyada ne sağlar?', 'Küçük kristallerin çözünüp büyük kristaller üzerinde yeniden çökerek süzgeç kâğıdından geçmeyen iri taneler oluşturmasını', ['Baryum sülfat katısının sıcak suda tamamen buharlaşarak çözeltiden gaz halinde ayrılmasını', 'Sülfat iyonlarının kükürt dioksite indirgenerek çökelek kütlesinin yarıya düşmesini', 'Ortak iyon etkisini ortadan kaldırarak çözeltideki tüm sodyum nitratın birlikte çökmesini'], 'Ostwald olgunlaşması olarak bilinen bu işlemde yüzey enerjisi yüksek çok ince tanecikler sıcak ortamda çözünür ve daha büyük kristallerin üzerine çökerek safsızlıkları dışlar, kolay süzülen iri kristaller oluşturur.'),
  ('Gümüş tiyosiyanat (AgSCN, Kçç = 1,0 × 10⁻¹²) ve gümüş bromür (AgBr, Kçç = 5,0 × 10⁻¹³) için eşit hacimde 2,0 × 10⁻⁶ M AgNO₃ ile 2,0 × 10⁻⁶ M NaSCN ve 2,0 × 10⁻⁶ M KBr içeren üç çözelti (toplam hacim 3 katına çıkacak biçimde) karıştırıldığında hangi çökelek oluşur?', 'Yalnızca AgBr için Qçç (4,4 × 10⁻¹³) < Kçç kontrolü yapıldığında her ikisi için de Qçç < Kçç çıktığından çökelme olmaz', ['Yalnızca Kçç değeri daha küçük olan sarımsı AgBr katısı dibe çöker', 'Hem AgSCN hem de AgBr katıları aynı anda beyaz çökelek olarak ayrılır', 'Yalnızca tiyosiyanat iyonları gümüşle birleşerek AgSCN katısını çöktürür'], 'Üç eşit hacim karıştığında her iyonun derişimi 1/3\'üne iner: [Ag⁺] = [SCN⁻] = [Br⁻] = (2,0/3)×10⁻⁶ = 6,67×10⁻⁷ M. Qçç = (6,67×10⁻⁷)² = 4,44×10⁻¹³! Dikkat: 4,44×10⁻¹³ hem AgSCN (1,0×10⁻¹²) hem AgBr (5,0×10⁻¹³) Kçç değerlerinden küçüktür; dolayısıyla hiçbir çökelme gerçekleşmez!'),
  ('Metan gazının klorlanması CH₄(g) + Cl₂(g) → CH₃Cl(g) + HCl(g) zincirleme radikal tepkimesinin yayılma adımları Cl· + CH₄ → HCl + ·CH₃ (ΔH₁ = +6 kJ) ve ·CH₃ + Cl₂ → CH₃Cl + Cl· (ΔH₂ = -109 kJ) şeklindedir. Buna göre net tepkimenin entalpi değişimi ve karanlıkta başlamama nedeni nedir?', 'Net ΔH = -103 kJ ekzotermiktir; karanlıkta başlamaması Cl-Cl bağını kıracak başlama enerjisinin (UV ışığı) gerekmesidir', ['Net ΔH = +103 kJ endotermiktir; tepkime boyunca sürekli morötesi ışık soğurulması zorunludur', 'İlk yayılma basamağı endotermik olduğu için toplam tepkime de dışarıdan ısı alarak yürür', 'Klor radikali ürünlerde tamamen tükendiği için Hess yasası radikal tepkimelerine uygulanamaz'], 'Ara basamaklar toplandığında radikaller sadeleşir ve net ΔH = +6 + (-109) = -103 kJ (ekzotermik) bulunur; UV ışığı yalnızca başlangıçta Cl₂ → 2Cl· aktifleşme engelini aşmak için gerekir.'),
  ('Doğal sularda çözünmüş demir(II) iyonları (Fe²⁺) yer altından yüzeye çıktığında havadaki oksijenle Fe³⁺ iyonlarına yükseltgenir ve pas renkli tortu çöker. Nötr pH = 7 civarında Fe²⁺ çökmezken Fe³⁺ iyonlarının hemen çökmesinin Kçç açısından nedeni nedir?', 'Fe(OH)₃\'ün Kçç değerinin (~10⁻³⁸) Fe(OH)₂\'nin Kçç değerinden (~10⁻¹⁵) çok daha küçük olması', ['Demir(III) hidroksitin çözünürlük çarpımının demir(II) hidroksitten milyonlarca kat büyük olması', 'Yükseltgenme sırasında suyun pH değerinin 7\'den 14\'e fırlayarak ortamı kuvvetli baz yapması', 'Oksijen gazının demir(II) iyonlarıyla ortak iyon oluşturarak çözünürlüğü artırması'], 'pH = 7\'de [OH⁻] = 10⁻⁷ M\'dir. Fe(OH)₂ için [Fe²⁺]·(10⁻⁷)² = 10⁻¹⁵ ⇒ 0,1 M Fe²⁺ bile çökmeden kalabilir; oysa Fe(OH)₃ için [Fe³⁺]·(10⁻⁷)³ = 10⁻³⁸ ⇒ [Fe³⁺] > 10⁻¹⁷ M olduğu anda kahverengi Fe(OH)₃ çöker!'),
  ('Hidrojen gazı ile etilen gazının C₂H₄(g) + H₂(g) → C₂H₆(g) katılma tepkimesinde platin (Pt) metal yüzeyi katalizör olarak kullanılır. Hidrojen ve etilenin platin yüzeyine kimyasal tutunması (kemisorpsiyon) olayının entalpi işareti nasıldır?', 'Gaz molekülleri metal yüzeyiyle yeni bağlar kurduğu ve düzensizlik azaldığı için ekzotermiktir', ['Yüzeye tutunma sırasında yalnızca bağ kırılması yaşandığı için her zaman endotermiktir', 'Fiziksel temas dışında hiçbir etkileşim olmadığından entalpi değişimi tam sıfırdır', 'Platin soy metal olduğu için gaz moleküllerini iterek ortamdan ısı soğurur'], 'Adsorpsiyon (özellikle kemisorpsiyon) sırasında gaz moleküllerinin serbestliği azalır (ΔS < 0) ve istemli gerçekleşebilmesi (ΔG < 0) için yüzeyle yeni bağlar kurarak dışarıya ısı vermesi (ΔH < 0, ekzotermik) zorunludur.'),
  ('Standart oluşum entalpileri kullanılarak NH₄NO₃(k) → N₂O(g) + 2H₂O(g) güldürücü gaz üretim tepkimesinin entalpisi hesaplanmak isteniyor. ΔH°f[NH₄NO₃(k)] = -365,6 kJ/mol, ΔH°f[N₂O(g)] = +82,0 kJ/mol ve ΔH°f[H₂O(g)] = -241,8 kJ/mol olduğuna göre tepkimenin ısı davranışı ve laboratuvar tehlikesi nedir?', 'ΔH° = -36,0 kJ olan ekzotermik bir bozunmadır; aşırı ısıtılırsa kendi ısısıyla hızlanıp patlamaya dönüşebilir', ['ΔH° = +36,0 kJ olan endotermik bir bozunmadır; ısıtıcı kapatıldığı anda tepkime tamamen durur', 'ΔH° = -767,2 kJ olan bir yanma tepkimesidir; başlaması için ortama saf oksijen gazı verilmelidir', 'ΔH° = +205,8 kJ olan bir süblimleşmedir; amonyum nitrat kimyasal yapısı değişmeden buharlaşır'], 'Ürünler = +82,0 + 2×(-241,8) = 82,0 - 483,6 = -401,6 kJ. ΔH° = -401,6 - (-365,6) = -36,0 kJ. Ekzotermik bir analiz tepkimesi olduğu için kontrolsüz yüksek sıcaklıkta patlayıcı bozunmaya (2NH₄NO₃ → 2N₂ + O₂ + 4H₂O, çok daha ekzotermik) geçebilir.'),
  ('25 °C\'de kalsiyum sülfat (CaSO₄, Kçç = 2,4 × 10⁻⁵) ve baryum sülfat (BaSO₄, Kçç = 1,0 × 10⁻¹⁰) katılarının aynı kapta aşırısı saf suyla çalkalanarak her iki katıyla da dengede bir çözelti hazırlanıyor. Dengedeki çözeltide [Ca²⁺] / [Ba²⁺] derişimleri oranı yaklaşık kaçtır?', '2,4 × 10⁵', ['4,9 × 10²', '2,4 × 10⁻⁵', '1,0 × 10⁵'], 'Aynı çözeltide her iki denge de aynı [SO₄²⁻] değerini paylaşır! Kçç(CaSO₄) / Kçç(BaSO₄) = ([Ca²⁺]·[SO₄²⁻]) / ([Ba²⁺]·[SO₄²⁻]) = [Ca²⁺] / [Ba²⁺] = (2,4×10⁻⁵) / (1,0×10⁻¹⁰) = 2,4 × 10⁵ bulunur.'),
  ('25 °C\'de gümüş arsenat (Ag₃AsO₄) katısının çözünürlük çarpımı Kçç = 1,08 × 10⁻²² olarak veriliyor. Buna göre doygun Ag₃AsO₄ sulu çözeltisinde gümüş iyonlarının molar derişimi ([Ag⁺]) kaç mol/L\'dir? (⁴√4 = 1,41)', '4,23 × 10⁻⁶ mol/L', ['1,41 × 10⁻⁶ mol/L', '3,00 × 10⁻⁶ mol/L', '1,08 × 10⁻⁵ mol/L'], 'Ag₃AsO₄(k) ⇌ 3Ag⁺ + AsO₄³⁻ için Kçç = (3s)³·s = 27s⁴ = 108 × 10⁻²⁴ ⇒ s⁴ = 4 × 10⁻²⁴ ⇒ s = 1,41 × 10⁻⁶ mol/L. Soruda [Ag⁺] = 3s sorulduğundan 3 × 1,41 × 10⁻⁶ = 4,23 × 10⁻⁶ mol/L olur!'),
  ('Bağ enerjileri tablosundaki ortalama değerler kullanılarak sıvı suyun oluştuğu H2(g) + 1/2 O2(g) → H2O(s) tepkimesinin ΔH değeri doğrudan hesaplanmak istendiğinde neden gerçek değerden sapma görülür?', 'Tablodaki bağ enerjileri yalnızca gaz fazı için geçerli olup suyun yoğunlaşma ısısını içermez', ['Sıvı fazdaki su moleküllerinde kovalent O-H bağları tamamen hidrojen bağına dönüşür', 'Oksijen gazının yarım katsayılı denklemlerde bağ enerjisi sıfır kabul edilir', 'Hidrojen gazının standart koşullarda atomik yapıda bulunması hesabı bozar'], 'Ortalama bağ enerjileri gaz fazındaki izole moleküller için tanımlanmıştır; ürün sıvı olduğunda gazdan sıvıya geçişteki yoğunlaşma entalpisi ayrıca eklenmelidir.'),
  ('Gaz fazındaki N2H4(g) + O2(g) → N2(g) + 2H2O(g) tepkimesinde ΔH = -585 kJ\'dür. N-H (391), O=O (498), N≡N (946) ve O-H (464) kJ/mol ise hidrazindeki N-N tekli bağ enerjisi kaç kJ/mol\'dür?', '155 kJ/mol', ['245 kJ/mol', '310 kJ/mol', '193 kJ/mol'], 'N2H4 yapısında 1 adet N-N ve 4 adet N-H bağı vardır. Kırılan: E(N-N) + 4×391 + 498 = E(N-N) + 2062. Oluşan: 946 + 4×464 = 2802. -585 = E(N-N) + 2062 - 2802 ⇒ E(N-N) = 155 kJ/mol.'),
  ('Benzen (C6H6) halkasındaki karbon-karbon bağlarının deneysel kopma enerjisinin, tekli C-C (348 kJ/mol) ile ikili C=C (614 kJ/mol) değerleri arasında yaklaşık 518 kJ/mol ölçülmesi neyi kanıtlar?', 'Pi elektronlarının halka boyunca delokalize olarak özdeş rezonans bağları oluşturduğunu', ['Benzen halkasındaki üç bağın tamamen iyonik, diğer üç bağın apolar kovalent olduğunu', 'Karbon atomlarının benzende sp3 hibritleşmesi yaparak düzgün dörtyüzlü geometri kurduğunu', 'Hidrojen atomlarının karbonlar arasına girerek köprü bağları meydana getirdiğini'], 'Benzende rezonans kararlılığı nedeniyle tüm C-C bağları özdeştir ve bağ derecesi 1,5 civarında olup enerjisi tekli ve ikili bağ arasındadır.'),
  ('F2(g) molekülünün bağ enerjisi 158 kJ/mol, H2(g) molekülünün 436 kJ/mol ve HF(g) gazının standart oluşum entalpisi -273 kJ/mol olduğuna göre H-F bağ enerjisi kaç kJ/mol\'dür?', '570 kJ/mol', ['297 kJ/mol', '546 kJ/mol', '612 kJ/mol'], '1/2 H2(g) + 1/2 F2(g) → HF(g) için ΔH = -273 kJ. -273 = (436/2 + 158/2) - E(H-F) = (218 + 79) - E(H-F) = 297 - E(H-F) ⇒ E(H-F) = 570 kJ/mol.'),
  ('Gaz fazındaki X2 + Y2 → 2XY tepkimesi ekzotermiktir. X-X ve Y-Y bağ enerjilerinin aritmetik ortalaması ile X-Y bağ enerjisi karşılaştırıldığında hangi sonuç kesinlikle doğrudur?', 'X-Y bağ enerjisi, X-X ve Y-Y bağ enerjilerinin aritmetik ortalamasından büyüktür', ['X-Y bağ enerjisi, X-X ve Y-Y bağ enerjilerinin toplamından daha büyüktür', 'X-X bağ enerjisi her durumda X-Y bağ enerjisinin iki katına eşittir', 'Y-Y bağ enerjisi, oluşan X-Y bağ enerjisinden daima daha yüksektir'], 'ΔH = E(X-X) + E(Y-Y) - 2E(X-Y) < 0 olduğundan E(X-Y) > [E(X-X) + E(Y-Y)] / 2 eşitsizliği kesinlikle sağlanır; elektronegatiflik farkı X-Y bağını güçlendirir.'),
  ('Fe2O3(k) + 3CO(g) → 2Fe(k) + 3CO2(g) (ΔH = -25 kJ) ve 3Fe2O3(k) + CO(g) → 2Fe3O4(k) + CO2(g) (ΔH = -47 kJ) veriliyor. Fe3O4(k) + CO(g) → 3FeO(k) + CO2(g) (ΔH = +19 kJ) ise FeO(k) + CO(g) → Fe(k) + CO2(g) için ΔH kaç kJ\'dür?', '-11 kJ', ['+11 kJ', '-33 kJ', '-6,3 kJ'], '1. denklem ×3: 3Fe2O3+9CO→6Fe+9CO2 (-75); 2. denklem ters: 2Fe3O4+CO2→3Fe2O3+CO (+47); 3. denklem ×2 ters: 6FeO+2CO2→2Fe3O4+2CO (-38). Toplanınca 6FeO+6CO→6Fe+6CO2 için ΔH = -75+47-38 = -66 kJ; 6\'ya bölününce -11 kJ.'),
  ('Born-Haber döngüsü, iyonik katıların örgü (kristal) enerjisini dolaylı yoldan hesaplamak için Hess yasasını kullanan bir çevrimdir. NaCl(k) için bu döngüde hangi adım ekzotermik olabilir?', 'Klor atomunun elektron alarak gaz fazında klorür iyonuna dönüşmesi ve örgü oluşumu', ['Sodyum katısının süblimleşmesi ve birinci iyonlaşma enerjisiyle elektron kopması', 'Klor molekülünün gaz fazında homolitik olarak atomlarına ayrışması', 'Sodyum gaz atomundan bir elektron koparılarak katyon haline geçmesi'], 'Süblimleşme, bağ kırılması ve iyonlaşma endotermikken, klorun elektron ilgisi (Cl(g)+e⁻→Cl⁻(g)) ve gaz iyonlarından kristal örgü oluşumu ekzotermiktir.'),
  ('C2H2(g), CO2(g) ve H2O(s) standart oluşum entalpileri sırasıyla +227, -393,5 ve -286 kJ/mol\'dür. Normal koşullarda 5,6 litre C2H2 gazı tamamen yandığında kaç kJ ısı açığa çıkar?', '325 kJ', ['1300 kJ', '650 kJ', '218,5 kJ'], 'C2H2 + 5/2 O2 → 2CO2 + H2O(s) için ΔH = [2×(-393,5) + (-286)] - 227 = -787 - 286 - 227 = -1300 kJ/mol. NŞA\'da 5,6 L gaz 0,25 moldür; açığa çıkan ısı 0,25 × 1300 = 325 kJ olur.'),
  ('P4(k) + 6Cl2(g) → 4PCl3(s) (ΔH = -1279 kJ) ve PCl3(s) + Cl2(g) → PCl5(k) (ΔH = -124 kJ) tepkimeleri veriliyor. 1 mol P4(k) katısından doğrudan PCl5(k) elde edilen P4(k) + 10Cl2(g) → 4PCl5(k) tepkimesinin ΔH değeri kaç kJ\'dür?', '-1775 kJ', ['-1403 kJ', '-783 kJ', '-1651 kJ'], 'İkinci tepkime 4 ile çarpılıp (4PCl3 + 4Cl2 → 4PCl5, ΔH = -496 kJ) birinci tepkime ile toplandığında 4PCl3\'ler birbirini götürür: ΔH = -1279 + (-496) = -1775 kJ.'),
  ('Metanın (CH4) eksik yanmasıyla CO(g) oluşma entalpisini doğrudan kalorimetrede ölçmek çok zordur çünkü aynı anda CO2(g) de oluşur. Hess yasası bu deneysel engeli nasıl aşar?', 'CH4 ve CO gazlarının tam yanma entalpileri ayrı ayrı ölçülüp cebirsel farkları alınarak', ['Tepkime kabına yüksek basınçta argon gazı basılıp CO2 oluşumu tamamen durdurularak', 'Kalorimetre suyuna sodyum klorür eklenip yalnızca CO gazının ısısı ayrıştırılarak', 'Sıcaklık mutlak sıfıra indirilip entropi terimi entalpiye eşitlenerek'], 'Tam yanma (aşırı O2 ile yalnız CO2 eldesi) kalorimetrede hatasız ölçülebildiğinden, CH4 ve CO\'nun tam yanma ısılarından Hess yasasıyla kısmi yanma ısısı kesin olarak hesaplanır.'),
  ('HCl(g) gazının standart oluşum entalpisi -92 kJ/mol ve suda çözünme denklemi HCl(g) → H⁺(suda) + Cl⁻(suda) için ΔH = -75 kJ/mol\'dür. Buna göre 1/2 H2(g) + 1/2 Cl2(g) → H⁺(suda) + Cl⁻(suda) tepkimesinin ΔH değeri kaç kJ\'dür?', '-167 kJ', ['-17 kJ', '+167 kJ', '-334 kJ'], '1/2 H2(g) + 1/2 Cl2(g) → HCl(g) (-92 kJ) ile HCl(g) → H⁺(suda) + Cl⁻(suda) (-75 kJ) basamakları toplandığında HCl(g) sadeleşir ve ΔH = -92 + (-75) = -167 kJ bulunur.'),
  ('2C(k) + H2(g) → C2H2(g) (ΔH = +227 kJ), C2H4(g) → 2C(k) + 2H2(g) (ΔH = -52 kJ) ve C2H6(g) → 2C(k) + 3H2(g) (ΔH = +85 kJ) veriliyor. C2H2(g) + C2H6(g) → 2C2H4(g) tepkimesinin ΔH değeri kaç kJ\'dür?', '-38 kJ', ['+38 kJ', '-142 kJ', '-208 kJ'], 'C2H2 solda kalır (-227), C2H6 solda aynen kalır (+85), ikinci denklem ters çevrilip 2 ile çarpılır (4C + 4H2 → 2C2H4, ΔH = 2 × (+52) = +104). Toplanınca: -227 + 85 + 104 = -38 kJ.'),
  ('Kalsiyum karbonat (CaCO3, MA = 100 g/mol) katısının belirli bir sıcaklıktaki Kçç değeri 4,9 × 10⁻⁹\'dur. Aynı sıcaklıkta 10 litre doymuş CaCO3 sulu çözeltisinde kaç miligram çözünen CaCO3 bulunur?', '70 mg', ['7 mg', '49 mg', '140 mg'], 'Kçç = s² = 49 × 10⁻¹⁰ ⇒ s = 7,0 × 10⁻⁵ mol/L. 10 litrede n = 7,0 × 10⁻⁴ mol çözünür; kütle m = 7,0 × 10⁻⁴ × 100 = 0,07 g = 70 mg olur.'),
  ('Kalsiyum fosfat, Ca3(PO4)2 katısının saf sudaki molar çözünürlüğü "s" mol/L olarak verildiğinde çözünürlük çarpımı Kçç ifadesi aşağıdakilerden hangisine eşittir?', '108s⁵', ['72s⁵', '36s⁵', '6s⁵'], 'Ca3(PO4)2(k) ⇌ 3Ca²⁺ + 2PO4³⁻ ayrışmasında [Ca²⁺] = 3s ve [PO4³⁻] = 2s olur; Kçç = (3s)³ × (2s)² = 27s³ × 4s² = 108s⁵ bulunur.'),
  ('Sabit sıcaklıkta dibinde 5 gram SrSO4 katısı bulunan 1 litrelik doymuş çözeltiye, dipteki katının yalnızca yarısını çözecek kadar saf su eklenip yeniden denge kuruluyor. Bu işlem sonucunda hangisi artar?', 'Çözeltide bulunan toplam Sr²⁺ ve SO4²⁻ iyonlarının mol sayısı', ['Çözeltinin birim hacmindeki Sr²⁺ iyonlarının molar derişimi', 'Stronsiyum sülfat katısının çözünürlük çarpımı (Kçç) değeri', 'Birim zamanda birim yüzeyden çözünen katının çözünme hızı'], 'Su eklendikçe katının bir kısmı daha çözündüğü için çözelti hala doymuştur; molar derişim ve Kçç sabit kalırken çözelti hacmi büyüdüğünden çözünen iyonların toplam mol sayısı artar.'),
  ('Cıva(I) klorür, doğada dimer katyon içeren Hg2Cl2 formülünde bulunur ve suda Hg2Cl2(k) ⇌ Hg2²⁺(suda) + 2Cl⁻(suda) şeklinde iyonlaşır. Kçç = 1,08 × 10⁻¹⁹ olduğuna göre doymuş çözeltideki Cl⁻ derişimi kaç mol/L\'dir?', '6,0 × 10⁻⁷ mol/L', ['3,0 × 10⁻⁷ mol/L', '9,0 × 10⁻⁷ mol/L', '1,2 × 10⁻⁶ mol/L'], 'Hg2²⁺ tek bir dimer katyon olduğundan [Hg2²⁺] = s ve [Cl⁻] = 2s olur; Kçç = 4s³ = 108 × 10⁻²¹ ⇒ s³ = 27 × 10⁻²¹ ⇒ s = 3,0 × 10⁻⁷ M ve [Cl⁻] = 2s = 6,0 × 10⁻⁷ mol/L bulunur.'),
  ('Alüminyum sülfür dışındaki suda hidroliz olmadan az çözünen Al(OH)3 için Kçç = 2,7 × 10⁻³¹ gibi son derece küçük bir değer verilir. Saf suya Al(OH)3 eklendiğinde gerçek [OH⁻] derişimi hesaplanırken neden yalnız 3s formülü kullanılamaz?', 'Saf suyun otoiyonizasyonundan gelen 1,0 × 10⁻⁷ M OH⁻ derişimi tuzdan gelenden çok daha büyük olduğu için', ['Alüminyum katyonları suyun kaynama noktasını düşürerek OH⁻ iyonlarını buharlaştırdığı için', 'Üç değerlikli katyon içeren tuzlarda Kçç bağıntısına katının yoğunluğu da eklendiği için', 'Hidroksit iyonları nötr suda anında hidrojen peroksit moleküllerine dönüştüğü için'], '27s⁴ = 2,7×10⁻³¹ denklemi yalnız başına s = 10⁻⁸ M verir ki 3s = 3×10⁻⁸ M değeri suyun kendi [OH⁻] = 10⁻⁷ M değerinden küçüktür; bu yüzden suyun otoiyonizasyonu ihmal edilemez.'),
  ('Sabit sıcaklıkta doymuş Ca(OH)2 sulu çözeltisinin 100 mL\'sini tamamen nötralleştirmek için 0,02 M HCl çözeltisinden 200 mL gerekmektedir. Buna göre Ca(OH)2 katısının Kçç değeri kaçtır?', '3,2 × 10⁻⁵', ['1,6 × 10⁻⁵', '4,0 × 10⁻⁶', '6,4 × 10⁻⁵'], 'Tam nötralleşmede n(OH⁻) = n(H⁺) = 0,02 M × 0,2 L = 4,0 × 10⁻³ mol. Başlangıçtaki 0,1 L çözeltide [OH⁻] = 4,0×10⁻³ / 0,1 = 4,0 × 10⁻² M = 2s ⇒ s = 2,0 × 10⁻² M. Kçç = 4s³ = 4 × (2×10⁻²)³ = 3,2 × 10⁻⁵.'),
  ('Aynı sıcaklıkta MgF2 katısının eşit derişimli (0,1 M) Mg(NO3)2 ve NaF sulu çözeltilerindeki molar çözünürlükleri karşılaştırıldığında hangisi doğrudur?', '0,1 M Mg(NO3)2 çözeltisindeki çözünürlüğü, 0,1 M NaF çözeltisindekinden büyüktür', ['0,1 M NaF çözeltisindeki çözünürlüğü, 0,1 M Mg(NO3)2 çözeltisindekinden büyüktür', 'Ortak iyon derişimleri eşit olduğundan her iki çözeltideki çözünürlük eşittir', 'NaF çözeltisinde Kçç karesiyle büyüdüğü için MgF2 tamamen çözünür'], 'MgF2 için Kçç = [Mg²⁺][F⁻]² bağıntısında [F⁻] karesiyle yer alır: 0,1 M Mg²⁺ ortamında x1 ≈ √(Kçç/0,1), 0,1 M F⁻ ortamında x2 ≈ Kçç/(0,1)² olur; çok küçük Kçç için √(10Kçç) >> 100Kçç olduğundan x1 > x2\'dir.'),
  ('Belirli bir sıcaklıkta Ag2CO3 katısının 0,1 M AgNO3 çözeltisindeki molar çözünürlüğü 8,0 × 10⁻¹⁰ mol/L olarak ölçülmüştür. Buna göre Ag2CO3 katısının aynı sıcaklıktaki saf sudaki molar çözünürlüğü kaç mol/L\'dir?', '1,26 × 10⁻⁴ mol/L', ['2,0 × 10⁻⁴ mol/L', '8,0 × 10⁻¹² mol/L', '4,0 × 10⁻⁴ mol/L'], '0,1 M Ag⁺ ortamında Kçç = (0,1)² × (8,0 × 10⁻¹⁰) = 8,0 × 10⁻¹². Saf suda Kçç = 4s³ = 8,0 × 10⁻¹² ⇒ s³ = 2,0 × 10⁻¹² ⇒ s = 2¹/³ × 10⁻⁴ ≈ 1,26 × 10⁻⁴ mol/L.'),
  ('25 °C\'de Fe(OH)2 katısının Kçç değeri 1,6 × 10⁻¹⁴\'tür. pH değeri 10 olan tamponlanmış bir sulu çözeltide Fe(OH)2 katısının maksimum molar çözünürlüğü kaç mol/L olur?', '1,6 × 10⁻⁶ mol/L', ['1,6 × 10⁻⁴ mol/L', '4,0 × 10⁻⁷ mol/L', '8,0 × 10⁻⁷ mol/L'], 'pH = 10 ise pOH = 4 ve tampon çözeltide [OH⁻] = 1,0 × 10⁻⁴ M sabit tutulur. Kçç = [Fe²⁺][OH⁻]² ⇒ 1,6 × 10⁻¹⁴ = [Fe²⁺] × (10⁻⁴)² ⇒ [Fe²⁺] = 1,6 × 10⁻⁶ mol/L.'),
  ('Suda nispeten daha çok çözünen bir tuz olan CaSO4 için Kçç = 2,4 × 10⁻³ değerinde varsayımsal bir MX tuzu modelinde, 0,05 M NaX çözeltisindeki çözünürlük hesaplanırken ihmal yapılmaması gerekirse hangi denklem çözülmelidir?', 'x(0,05 + x) = 2,4 × 10⁻³', ['0,05x = 2,4 × 10⁻³', 'x(0,05 + 2x)² = 2,4 × 10⁻³', 'x² = 2,4 × 10⁻³ + 0,05'], 'Kçç değeri büyük olduğunda tuzdan gelen x derişimi 0,05 M yanında ihmal edilemeyecek kadar büyük çıkar; bu nedenle tam ikinci dereceden x(0,05 + x) = Kçç denklemi çözülür.'),
  ('Diş minesinin ana bileşeni olan hidroksiapatit Ca5(PO4)3OH katısı ağızda Ca5(PO4)3OH(k) ⇌ 5Ca²⁺ + 3PO4³⁻ + OH⁻ dengesindedir. Florürlü diş macunlarının çürümeyi önleme mekanizması çözünürlük dengesiyle nasıl açıklanır?', 'OH⁻ yerine F⁻ geçerek Kçç değeri daha küçük ve aside daha dirençli floroapatit oluşturur', ['Florür iyonları ağızdaki tüm kalsiyum iyonlarını gaz fazına geçirerek bakterileri kurutur', 'Diş macunundaki sodyum iyonları fosfatlarla birleşip Kçç değerini sonsuza çıkarır', 'Florür eklendiğinde tükürüğün sıcaklığı düşerek endotermik çözünme hızlanır'], 'Ca5(PO4)3F (floroapatit) katısının Kçç değeri hidroksiapatitten çok daha küçüktür ve F⁻ zayıf bazik olduğundan bakterilerin ürettiği asitlere karşı çok daha az çözünür.'),
  ('25 °C\'de Cr(OH)3 katısının Kçç değeri 2,0 × 10⁻³¹\'dir. Cr(OH)3 katısının molar çözünürlüğünün tam 2,0 × 10⁻¹⁰ mol/L olması için çözeltinin pH değeri kaçta sabitlenmelidir?', 'pH = 7', ['pH = 9', 'pH = 5', 'pH = 11'], 'Kçç = [Cr³⁺][OH⁻]³ ⇒ 2,0 × 10⁻³¹ = (2,0 × 10⁻¹⁰) × [OH⁻]³ ⇒ [OH⁻]³ = 1,0 × 10⁻²¹ ⇒ [OH⁻] = 1,0 × 10⁻⁷ M olur; buradan pOH = 7 ve 25 °C\'de pH = 7 bulunur.'),
  ('1 litre 0,02 M NaBr sulu çözeltisinde sabit sıcaklıkta en fazla 9,4 × 10⁻¹⁰ gram AgBr (MA = 188 g/mol) katısı çözünebildiğine göre bu sıcaklıkta AgBr\'nin Kçç değeri kaçtır?', '1,0 × 10⁻¹³', ['5,0 × 10⁻¹²', '2,0 × 10⁻¹³', '1,88 × 10⁻¹¹'], 'Çözünen mol sayısı n = (9,4 × 10⁻¹⁰ g) / 188 g/mol = 0,05 × 10⁻¹⁰ = 5,0 × 10⁻¹² mol. 1 L çözeltide [Ag⁺] = 5,0 × 10⁻¹² M ve [Br⁻] ≈ 0,02 M olduğundan Kçç = (5,0 × 10⁻¹²) × 0,02 = 1,0 × 10⁻¹³ olur.'),
  ('0,1 M Mg²⁺ iyonu içeren bir sulu çözeltiye sabit sıcaklıkta hacim değişimi olmadan baz ekleniyor. Mg(OH)2 (Kçç = 1,0 × 10⁻¹¹) katısının çökelmeye başladığı sınır pH değeri kaçtır? (25 °C)', 'pH = 9', ['pH = 5', 'pH = 10', 'pH = 8'], 'Q = Kçç sınırında (0,1) × [OH⁻]² = 1,0 × 10⁻¹¹ ⇒ [OH⁻]² = 1,0 × 10⁻¹⁰ ⇒ [OH⁻] = 1,0 × 10⁻⁵ M. Buradan pOH = 5 ve 25 °C\'de pH = 14 - 5 = 9 bulunur.'),
  ('Eşit hacimlerde 0,2 M AgNO3 ve 0,4 M NaCl sulu çözeltileri karıştırılıp çökelme tamamlandıktan sonra dengeye ulaşan çözeltideki Ag⁺ iyonu derişimi kaç mol/L kalır? (AgCl için Kçç = 1,0 × 10⁻¹⁰)', '1,0 × 10⁻⁹ mol/L', ['5,0 × 10⁻¹⁰ mol/L', '1,0 × 10⁻⁵ mol/L', '0,1 mol/L'], 'Eşit hacimde karışınca başlangıçta [Ag⁺] = 0,1 M ve [Cl⁻] = 0,2 M olur. Ag⁺ sınırlayıcı bileşen olarak neredeyse tamamen çöker, geriye [Cl⁻] = 0,2 - 0,1 = 0,1 M artar. Dengede [Ag⁺] × 0,1 = 1,0 × 10⁻¹⁰ ⇒ [Ag⁺] = 1,0 × 10⁻⁹ M kalır.'),
  ('Aynı çözelti içinde 0,01 M Cl⁻ ve 0,01 M I⁻ iyonları bulunmaktadır. Bu çözeltiye damla damla AgNO3 eklendiğinde hangi tuz önce çöker ve ikinci tuz çökmeye başladığında ilk iyonun derişimi ne olur? (Kçç(AgCl) = 1,8×10⁻¹⁰, Kçç(AgI) = 9,0×10⁻¹⁷)', 'Önce AgI çöker; AgCl çökmeye başladığında [I⁻] = 5,0 × 10⁻⁹ M olur', ['Önce AgCl çöker; AgI çökmeye başladığında [Cl⁻] = 2,0 × 10⁻⁵ M olur', 'İki iyonun başlangıç derişimi eşit olduğu için AgCl ve AgI aynı anda çöker', 'Önce AgI çöker; AgCl çökmeye başladığında [I⁻] tamamen sıfırlanmış olur'], 'AgI çökmesi için gereken [Ag⁺] = 9,0×10⁻¹⁷/0,01 = 9,0×10⁻¹⁵ M, AgCl için ise 1,8×10⁻¹⁰/0,01 = 1,8×10⁻⁸ M\'dir; önce AgI çöker. [Ag⁺] = 1,8×10⁻⁸ M olduğunda [I⁻] = 9,0×10⁻¹⁷ / 1,8×10⁻⁸ = 5,0 × 10⁻⁹ M olur.'),
  ('Bir sulu çözeltide hem 0,01 M Ba²⁺ hem de 0,01 M Sr²⁺ iyonları vardır. Çözeltiye yavaşça Na2SO4 eklendiğinde SrSO4 çökmeye başladığı anda çözeltide kalan Ba²⁺ yüzdesi kaçtır? (Kçç(BaSO4) = 1,0×10⁻¹⁰, Kçç(SrSO4) = 2,5×10⁻⁷)', '%0,04', ['%0,4', '%4,0', '%0,004'], 'SrSO4 çökmeye başladığında [SO4²⁻] = 2,5×10⁻⁷ / 0,01 = 2,5 × 10⁻⁵ M olur. Bu anda [Ba²⁺] = 1,0×10⁻¹⁰ / (2,5×10⁻⁵) = 4,0 × 10⁻⁶ M kalır. Yüzde kalan: (4,0×10⁻⁶ / 0,01) × 100 = %0,04.'),
  ('25 °C\'de 0,02 M NH3 ve 0,18 M NH4Cl içeren tampon çözeltiye eşit hacimde 0,04 M MnCl2 çözeltisi ekleniyor. NH3 için Kb = 1,8 × 10⁻⁵ ve Mn(OH)2 için Kçç = 1,6 × 10⁻¹³ ise ne gözlenir?', 'Q = 8,0 × 10⁻¹⁴ < Kçç olduğundan Mn(OH)2 çökelmesi gözlenmez', ['Q = 1,6 × 10⁻¹³ = Kçç olduğundan çözelti tam doygunluk sınırındadır', 'Q = 3,2 × 10⁻¹³ > Kçç olduğundan kapta Mn(OH)2 katısı çöker', 'Q = 4,0 × 10⁻¹² > Kçç olduğundan amonyum hidroksit katısı çöker'], 'Karışımda NH3/NH4⁺ mol oranı değişmez: [OH⁻] = Kb × (0,02/0,18) = 1,8×10⁻⁵ × (1/9) = 2,0 × 10⁻⁶ M. Eşit hacimden [Mn²⁺] = 0,04/2 = 0,02 M. Q = 0,02 × (2,0×10⁻⁶)² = 0,02 × 4,0×10⁻¹² = 8,0 × 10⁻¹⁴ < 1,6 × 10⁻¹³ (çökmez).'),
  ('500 mL 0,04 M CaCl2 ve 500 mL 0,04 M Na2CO3 çözeltileri sabit sıcaklıkta karıştırılıyor. CaCO3 (MA = 100 g/mol, Kçç = 4,0 × 10⁻⁹) çökelmesi tamamlandığında kaç gram katı dibe çöker ve dengedeki [Ca²⁺] kaç M olur?', '2,0 gram katı çöker ve dengede [Ca²⁺] = 6,32 × 10⁻⁵ M olur', ['4,0 gram katı çöker ve dengede [Ca²⁺] = 4,0 × 10⁻⁹ M olur', '2,0 gram katı çöker ve dengede [Ca²⁺] = 2,0 × 10⁻² M olur', '1,0 gram katı çöker ve dengede [Ca²⁺] = 6,32 × 10⁻⁵ M olur'], 'n(Ca²⁺) = 0,5×0,04 = 0,02 mol, n(CO3²⁻) = 0,02 mol. Neredeyse tamamı (0,02 mol × 100 = 2,0 g) çöker. Eşdeğer miktarda karıştıkları için 1 L doymuş CaCO3 çözeltisi kalır: [Ca²⁺] = √(4,0×10⁻⁹) = √(40×10⁻¹⁰) ≈ 6,32 × 10⁻⁵ M.'),
  ('Bir öğrenci 0,02 M Pb(NO3)2 ve 0,02 M KCl çözeltilerini eşit hacimde karıştırıp PbCl2 (Kçç = 1,6 × 10⁻⁵) çökeceğini iddia ediyor. Öğrencinin bu iddiası nicel olarak değerlendirildiğinde hangisi doğrudur?', 'İddia yanlıştır; karışımda Q = 1,0 × 10⁻⁶ < Kçç olduğundan çökelme gerçekleşmez', ['İddia doğrudur; karışımda Q = 4,0 × 10⁻⁶ < Kçç olmasına rağmen kurşun çöker', 'İddia doğrudur; karışımda Q = 8,0 × 10⁻⁶ > Kçç olduğundan beyaz çökelti oluşur', 'İddia yanlıştır; karışımda yalnız KNO3 tuzu Q > Kçç koşulunu sağlayıp çöker'], 'Eşit hacimde karışınca [Pb²⁺] = 0,01 M ve [Cl⁻] = 0,01 M olur. PbCl2 için Q = [Pb²⁺][Cl⁻]² = (0,01) × (0,01)² = 1,0 × 10⁻⁶ bulunur. Q < 1,6 × 10⁻⁵ (Kçç) olduğu için çökelme olmaz.'),
  ('Sabit sıcaklıkta 0,1 M Cl⁻, 0,01 M Br⁻ ve 0,001 M CrO4²⁻ içeren bir çözeltiye katı AgNO3 yavaşça ekleniyor. Kçç değerleri AgCl (1,8×10⁻¹⁰), AgBr (5,0×10⁻¹³) ve Ag2CrO4 (9,0×10⁻¹²) ise çökelme sırası nasıldır?', 'Önce AgBr, sonra AgCl, en son Ag2CrO4 çöker', ['Önce AgCl, sonra AgBr, en son Ag2CrO4 çöker', 'Önce Ag2CrO4, sonra AgBr, en son AgCl çöker', 'Önce AgBr, sonra Ag2CrO4, en son AgCl çöker'], 'Çökelme için gereken minimum [Ag⁺] değerleri: AgCl için 1,8×10⁻¹⁰ / 0,1 = 1,8×10⁻⁹ M; AgBr için 5,0×10⁻¹³ / 0,01 = 5,0×10⁻¹¹ M; Ag2CrO4 için √(9,0×10⁻¹² / 10⁻³) = √(9,0×10⁻⁹) = 9,49×10⁻⁵ M. En küçük [Ag⁺] gerektiren AgBr ilk, Ag2CrO4 son çöker.'),
  ('Gaz fazında N2O4(g) → 2NO2(g) tepkimesinin entalpisi +58 kJ, N2(g) + 2O2(g) → 2NO2(g) tepkimesinin entalpisi +66 kJ\'dür. Buna göre 2N2O4(g) → 2N2(g) + 4O2(g) ayrışma tepkimesinin ΔH değeri kaç kJ\'dür?', '-16 kJ', ['+16 kJ', '-124 kJ', '+248 kJ'], 'N2O4 → 2NO2 (+58) ile 2NO2 → N2 + 2O2 (-66) toplanırsa N2O4 → N2 + 2O2 için ΔH = 58 - 66 = -8 kJ bulunur; denklem 2 ile çarpıldığında ΔH = 2 × (-8) = -16 kJ olur.'),
  ('Bir MX(k) iyonik katısının örgü (kristal) ayrışma enerjisi MX(k) → M⁺(g) + X⁻(g) için +780 kJ/mol, gaz iyonlarının suyla hidratlaşma entalpileri toplamı ise -765 kJ/mol\'dür. Hess yasasına göre bu tuzun suda çözünmesi ve Kçç sıcaklıkla ilişkisi nasıldır?', 'ΔHçöz = +15 kJ/mol olup endotermiktir; sıcaklık artırıldığında Kçç değeri büyür', ['ΔHçöz = -15 kJ/mol olup ekzotermiktir; sıcaklık artırıldığında Kçç değeri küçülür', 'ΔHçöz = +1545 kJ/mol olup endotermiktir; sıcaklık artırıldığında Kçç küçülür', 'ΔHçöz = +15 kJ/mol olup endotermiktir; ancak Kçç sıcaklıktan hiç etkilenmez'], 'Hess yasasına göre ΔHçözünme = ΔHörgü + ΔHhidratlaşma = (+780) + (-765) = +15 kJ/mol (endotermik). Endotermik çözünmede ısıtma dengeyi iyonlar yönüne kaydırarak Kçç\'yi büyütür.'),
  ('PH3(g) molekülünün yanma denklemi 2PH3(g) + 4O2(g) → P2O5(k) + 3H2O(g) için ΔH = -2290 kJ\'dür. P2O5(k) ve H2O(g) standart oluşum entalpileri sırasıyla -1492 ve -242 kJ/mol ise PH3(g) standart oluşum entalpisi kaç kJ/mol\'dür?', '+36 kJ/mol', ['-36 kJ/mol', '+72 kJ/mol', '+18 kJ/mol'], 'ΔHtepkime = [ΔHf(P2O5) + 3×ΔHf(H2O)] - 2×ΔHf(PH3) ⇒ -2290 = [-1492 + 3×(-242)] - 2x = -1492 - 726 - 2x = -2218 - 2x ⇒ 2x = 72 ⇒ x = +36 kJ/mol.'),
  ('CS2(s) + 3O2(g) → CO2(g) + 2SO2(g) (ΔH = -1077 kJ), C(k) + O2(g) → CO2(g) (ΔH = -393,5 kJ) ve S(k) + O2(g) → SO2(g) (ΔH = -297 kJ) veriliyor. C(k) + 2S(k) → CS2(s) tepkimesinin entalpi değişimi kaç kJ\'dür?', '+89,5 kJ', ['-89,5 kJ', '+186,5 kJ', '-386,5 kJ'], '2. denklem aynen (-393,5), 3. denklem ×2 (-594), 1. denklem ters (+1077) alınıp toplanırsa CO2, SO2 ve O2\'ler sadeleşir: ΔH = -393,5 - 594 + 1077 = -987,5 + 1077 = +89,5 kJ.'),
  ('0,04 M AgNO3 çözeltisinin 250 mL\'si ile 0,04 M K2CrO4 çözeltisinin 250 mL\'si sabit sıcaklıkta karıştırılıyor. Çökelme tamamlandığında dengedeki çözeltide Ag⁺ iyonu derişimi kaç mol/L olur? (Ag2CrO4 için Kçç = 9,0 × 10⁻¹²)', '3,0 × 10⁻⁵ mol/L', ['1,5 × 10⁻⁵ mol/L', '6,0 × 10⁻⁵ mol/L', '9,0 × 10⁻¹⁰ mol/L'], 'Karışım anında (500 mL): [Ag⁺] = 0,02 M ve [CrO4²⁻] = 0,02 M olur. 2Ag⁺ + CrO4²⁻ → Ag2CrO4(k) stokiyometrisine göre 0,02 M Ag⁺ tamamen harcanırken 0,01 M CrO4²⁻ harcanır ve 0,01 M CrO4²⁻ artar; [Ag⁺]² × 0,01 = 9,0 × 10⁻¹² ⇒ [Ag⁺] = 3,0 × 10⁻⁵ mol/L bulunur.'),
  ('Termokimyada bağ enerjileriyle hesaplanan tepkime entalpisi ile standart oluşum entalpilerinden (Hess yasası) hesaplanan tepkime entalpisi karşılaştırıldığında hangisi bilimsel olarak daha kesindir ve neden?', 'Standart oluşum entalpileriyle yapılan hesap daha kesindir; çünkü bağ enerjileri farklı moleküllerden alınan ortalama değerlerdir', ['Bağ enerjileriyle yapılan hesap daha kesindir; çünkü her kovalent bağın enerjisi evrensel bir sabittir', 'İki yöntem de her türlü katı, sıvı ve sulu çözelti tepkimesinde virgülden sonra tam aynı sonucu verir', 'Bağ enerjileri yöntemi iyonik tuzların sulu çözeltilerdeki çökelme ısılarını da doğrudan verdiği için üstündür'], 'Tablolardaki bağ enerjileri çeşitli moleküllerden elde edilen "ortalama" gaz fazı değerleridir; oysa standart oluşum entalpileri her bileşiğin gerçek fiziksel hali ve kendine özgü elektronik yapısı için doğrudan ölçülmüş kesin değerlerdir.'),
  ('Ca(OH)2(k) + 2H⁺(suda) → Ca²⁺(suda) + 2H2O(s) tepkimesinin ΔH değeri -130 kJ ve H⁺(suda) + OH⁻(suda) → H2O(s) nötralleşme tepkimesinin ΔH değeri -57 kJ\'dür. Buna göre Ca(OH)2(k) katısının suda çözünme entalpisi kaç kJ/mol\'dür?', '-16 kJ/mol', ['+16 kJ/mol', '-73 kJ/mol', '-244 kJ/mol'], 'Ca(OH)2(k) → Ca²⁺(suda) + 2OH⁻(suda) denklemini elde etmek için 1. denklem aynen alınır (-130 kJ), 2. denklem ters çevrilip 2 ile çarpılır (2H2O → 2H⁺ + 2OH⁻, ΔH = +114 kJ). Toplanınca ΔHçöz = -130 + 114 = -16 kJ/mol bulunur.'),
  ('Suda az çözünen AgCN katısının doymuş sulu çözeltisine sabit sıcaklıkta kuvvetli bir asit eklendiğinde (HCN zayıf asittir, Ka = 6,2 × 10⁻¹⁰) çözünürlük dengesi ve Q-Kçç ilişkisi anlık olarak nasıl değişir?', 'H⁺ iyonları CN⁻ ile HCN oluşturarak anlık Q değerini Kçç\'nin altına düşürür ve dipteki AgCN çözünür', ['Eklenen asit Kçç değerini büyüttüğü için Q sabit kalırken yeni bir denge kurulur', 'Siyanür iyonları asidik ortamda Ag⁺ ile çift tuz oluşturarak Q değerini Kçç üstüne çıkarır', 'Zayıf asit oluşumu Kçç bağıntısını geçersiz kıldığından AgCN tamamen çökelir'], 'H⁺ + CN⁻ ⇌ HCN tepkimesi serbest [CN⁻] derişimini aniden düşürür; böylece anlık iyon çarpımı Q = [Ag⁺][CN⁻] < Kçç durumuna geçer ve sistem yeniden Q = Kçç olana dek AgCN katısını çözer.'),
  ('25 °C\'de AgBr (Kçç = 5,0 × 10⁻¹³) katısının 1 litre saf sudaki çözünürlüğü yanında, Ag⁺ + 2NH3 ⇌ [Ag(NH3)2]⁺ (Koluşum = 1,8 × 10⁷) dengesi varlığında AgBr(k) + 2NH3(suda) ⇌ [Ag(NH3)2]⁺(suda) + Br⁻(suda) net tepkimesinin denge sabiti K kaçtır?', '9,0 × 10⁻⁶', ['2,78 × 10⁻²⁰', '1,8 × 10⁻⁵', '3,6 × 10⁻⁶'], 'İki denge denklemi taraf tarafa toplandığında (Hess yasasının denge sabitlerindeki karşılığı olarak) net denge sabiti K = Kçç × Koluşum = (5,0 × 10⁻¹³) × (1,8 × 10⁷) = 9,0 × 10⁻⁶ olur.'),
  ('25 °C\'de Mg(OH)2 (Kçç = 1,8 × 10⁻¹¹) katısının dibinde katısı bulunan doymuş çözeltisinin 1 litresine sabit sıcaklıkta 0,02 mol katı MgCl2 eklenip çözünüyor. Yeniden denge kurulduğunda çözeltinin pH değeri yaklaşık kaç olur? (log 3 = 0,48)', 'pH = 9,48', ['pH = 4,52', 'pH = 10,48', 'pH = 8,52'], '0,02 M Mg²⁺ ortak iyon ortamında [Mg²⁺][OH⁻]² = 1,8 × 10⁻¹¹ ⇒ 0,02 × [OH⁻]² = 1,8 × 10⁻¹¹ ⇒ [OH⁻]² = 9,0 × 10⁻¹⁰ ⇒ [OH⁻] = 3,0 × 10⁻⁵ M. pOH = 5 - log 3 = 5 - 0,48 = 4,52 ve pH = 14 - 4,52 = 9,48 olur.'),
];
